-- ============================================================
--  181_experiencias_gestion_calidad.sql — Experiencias de clase: Curso de Gestión de Calidad Farmacéutica
--
--  Generado por scripts/generar-migracion-experiencias.mjs gestion-calidad
--  a partir de contenido/experiencias/gestion-calidad. No editar a mano.
--
--  35 clases con experiencia interactiva (mapa conceptual,
--  mapa de proceso, caso, errores frecuentes, repaso, resumen y
--  referencias): 209.024 caracteres de lectura, mínimo
--  3.678 por clase.
--
--  Por clase: si no está, avisa y sigue; si no tiene experiencia,
--  retira (borrado lógico) el texto corto de la siembra e inserta la
--  experiencia como primer bloque, conservando videos y enlaces; si ya
--  la tiene, la actualiza. Si el curso está publicado, deja aprobada
--  una versión nueva (077). Nunca detiene el arranque.
-- ============================================================

DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Gestión de Calidad Farmacéutica$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Gestión de Calidad Farmacéutica$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El lote que salió bien por casualidad","texto":"Un laboratorio colombiano libera un lote de tabletas que cumple todas las especificaciones. Semanas después, en una autoinspección, alguien descubre que la balanza de dispensación llevaba tres meses sin verificación, que el operario que pesó no había recibido la capacitación del procedimiento nuevo y que nadie revisó el cambio de proveedor del excipiente. El lote cumplió, pero nadie puede demostrar por qué. Esa es la diferencia entre tener buenos resultados y tener un **sistema de gestión de calidad**: el sistema hace que el buen resultado sea la consecuencia esperada, no un golpe de suerte."},"objetivos":["Explicar qué es un sistema de gestión de calidad (SGC) y por qué una organización farmacéutica lo necesita además de cumplir especificaciones.","Ubicar los tres marcos que integra el curso: ICH Q10, ISO 9001:2015 y la normativa colombiana del INVIMA y el Ministerio de Salud.","Reconocer la ruta del curso y cómo se conecta con los cursos de BPM, CAPA, auditoría, riesgos y documentación."],"conceptos":[{"icono":"Network","termino":"Sistema de gestión de calidad","definicion":"Conjunto de procesos, responsabilidades, recursos y documentos que una organización usa para dirigir y controlar lo que hace en relación con la calidad. No es un manual ni un departamento: es la forma en que trabaja toda la organización."},{"icono":"ShieldCheck","termino":"Calidad del producto","definicion":"Que el medicamento o el servicio cumpla de forma consistente los requisitos de identidad, pureza, potencia, seguridad y desempeño con los que fue autorizado, lote tras lote."},{"icono":"Landmark","termino":"Requisito regulatorio","definicion":"Lo que exige la autoridad sanitaria para fabricar, importar, distribuir o dispensar medicamentos. En Colombia lo fijan el Ministerio de Salud y Protección Social y lo vigila el INVIMA o la secretaría de salud."},{"icono":"RefreshCw","termino":"Mejora continua","definicion":"La actividad recurrente de aumentar el desempeño. En un SGC se alimenta de datos: desviaciones, quejas, auditorías, indicadores y revisión por la dirección."}],"secciones":[{"titulo":"Cumplir no es lo mismo que gestionar","parrafos":["Un medicamento no se puede «probar hasta la calidad». El análisis de control de calidad examina una muestra, no cada tableta; si el proceso no está controlado, un lote puede cumplir por azar y el siguiente fallar sin aviso. Por eso las Buenas Prácticas de Manufactura (BPM) y las guías internacionales insisten en que la calidad se **construye** en cada etapa: en la selección de proveedores, en el diseño del proceso, en la capacitación del personal, en el control de los cambios y en la revisión de lo que ocurre.","Un **sistema de gestión de calidad** es el marco que organiza todo eso. Define qué procesos tiene la organización, quién es responsable de cada uno, cómo se mide su desempeño, qué se hace cuando algo falla y cómo la dirección revisa periódicamente si el sistema funciona. Cuando el SGC está bien diseñado, una desviación como la de la balanza del ejemplo se detecta a tiempo, se investiga y se corrige su causa, en lugar de descubrirse por accidente."]},{"titulo":"Tres marcos que se integran","parrafos":["**ICH Q10**, la guía armonizada del Consejo Internacional de Armonización, describe un modelo de **sistema de calidad farmacéutico** para todo el ciclo de vida del producto: desarrollo, transferencia de tecnología, fabricación comercial y discontinuación. Se apoya en las BPM y agrega elementos de gestión como la revisión por la dirección, la gestión del conocimiento y la gestión de riesgos.","**ISO 9001:2015** es la norma internacional de requisitos para un SGC aplicable a cualquier organización. Aporta la estructura de gestión: contexto de la organización, liderazgo, planificación con base en riesgos, apoyo, operación, evaluación del desempeño y mejora. Muchas droguerías, distribuidores, laboratorios de análisis y prestadores de servicio farmacéutico la usan para certificarse.","La **normativa colombiana** es la obligatoria. El Decreto 677 de 1995 regula los registros sanitarios y el control de calidad de los medicamentos; la Resolución 1160 de 2016 adopta los manuales de BPM y las guías de inspección que aplica el INVIMA; y para el servicio farmacéutico, el Decreto 780 de 2016 (que compila el Decreto 2200 de 2005) y la Resolución 1403 de 2007 exigen un sistema de gestión de calidad propio. En este curso aprenderás a integrar los tres marcos en un solo sistema, sin duplicar documentos."]},{"titulo":"La ruta del curso","parrafos":["El curso tiene cinco unidades. La **unidad 1** construye los fundamentos: historia de la calidad, aportes de los grandes autores, por qué el medicamento exige un sistema propio, los siete principios de ISO 9000 y el vocabulario básico. La **unidad 2** recorre el marco normativo colombiano. La **unidad 3** compara los modelos ICH Q10 e ISO 9001:2015. La **unidad 4** baja el sistema a procesos, indicadores y revisión por la dirección. La **unidad 5** cierra con mejora continua, gestión del cambio y cultura de calidad, y una hoja de ruta para implementar o fortalecer un SGC.","Este curso es la columna vertebral de la línea de calidad farmacéutica de Edvanta. Los temas que aquí se presentan como parte del sistema se profundizan en cursos hermanos: **BPM**, **gestión de desviaciones y CAPA**, **auditoría de calidad**, **gestión de riesgos** y **buenas prácticas de documentación**. Cuando un tema aparezca aquí de forma general, sabrás dónde estudiarlo a fondo."]}],"errores":[{"error":"Creer que el SGC es el manual de calidad o la oficina de aseguramiento.","correccion":"El SGC es la forma de trabajar de toda la organización; el manual solo lo describe y aseguramiento lo coordina."},{"error":"Montar un sistema para ISO 9001 y otro para BPM.","correccion":"Integra los requisitos en un solo sistema de procesos y documentos; las BPM son obligatorias y la norma ISO agrega estructura de gestión."},{"error":"Medir el sistema solo por los resultados de los lotes.","correccion":"Mide también los procesos: desviaciones, CAPA eficaces, quejas, auditorías, capacitación y cambios controlados."}],"comprueba":[{"pregunta":"¿Por qué no basta con analizar el producto terminado?","respuesta":"Porque el análisis examina una muestra y no puede demostrar que todo el lote se fabricó bajo control. La calidad se construye en cada etapa del proceso."},{"pregunta":"¿Qué aporta ICH Q10 que no aportan solas las BPM?","respuesta":"Un modelo de gestión para todo el ciclo de vida, con responsabilidad de la dirección, gestión del conocimiento, gestión de riesgos y mejora continua."},{"pregunta":"¿Qué normas colombianas exigen un SGC al servicio farmacéutico?","respuesta":"El Decreto 780 de 2016, que compila el Decreto 2200 de 2005, y la Resolución 1403 de 2007."}],"resumen":["Un SGC hace que el buen resultado sea **consecuencia del sistema**, no de la suerte.","El curso integra **ICH Q10**, **ISO 9001:2015** y la **normativa colombiana** en un solo sistema.","La calidad se **construye** en el proceso; el análisis final no la crea."],"referencias":[{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"},{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos.","url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf"}],"imagenes":[{"ubicacion":"Junto a la situación inicial","descripcion":"Ilustración de un laboratorio farmacéutico con tres capas superpuestas que representan ICH Q10, ISO 9001 y la normativa colombiana, en la paleta de Edvanta.","alt":"Tres marcos de calidad que se integran en un sistema de gestión farmacéutico"}],"keywords":["sistema de gestión de calidad farmacéutica","qué es un sgc","ich q10 e iso 9001","gestión de calidad en la industria farmacéutica","calidad del servicio farmacéutico colombia","curso gestión de calidad farmacéutica"],"mapa":{"centro":"SGC farmacéutico","ramas":[{"titulo":"ICH Q10","icono":"Globe","nodos":["Modelo de sistema de calidad farmacéutico","Ciclo de vida del producto","Responsabilidad de la dirección"]},{"titulo":"ISO 9001:2015","icono":"Award","nodos":["Enfoque por procesos","Pensamiento basado en riesgos","Ciclo PHVA"]},{"titulo":"Colombia","icono":"Landmark","nodos":["Decreto 677 de 1995","BPM por Resolución 1160 de 2016","Servicio farmacéutico: Decreto 780 de 2016 y Resolución 1403 de 2007"]},{"titulo":"Herramientas","icono":"Wrench","nodos":["Procesos e indicadores","Gestión del cambio","Revisión por la dirección"]}]},"caso":{"titulo":"Un laboratorio que «siempre ha cumplido»","contexto":"La gerente de un laboratorio de productos no estériles dice que no necesita fortalecer su sistema de calidad porque en diez años ningún lote ha salido fuera de especificaciones y el INVIMA le renovó el certificado de BPM. En la última revisión, sin embargo, hay 40 desviaciones abiertas, la mitad sin causa raíz y varias repetidas.","pregunta":"¿Cuál es la lectura más acertada de la situación?","opciones":[{"texto":"El sistema funciona: si los lotes cumplen, las desviaciones son un tema administrativo.","correcta":false,"retro":"Cumplir especificaciones no demuestra control. Desviaciones repetidas sin causa raíz indican que el sistema no aprende y que el riesgo de una falla mayor sigue presente."},{"texto":"El sistema tiene una falla de gestión: no investiga ni corrige causas, y eso es justo lo que un SGC debe asegurar.","correcta":true,"retro":"Un SGC se mide por su capacidad de detectar, investigar, corregir y prevenir. Las desviaciones repetidas son un indicador de que esos procesos no están funcionando."},{"texto":"Basta con cerrar las desviaciones abiertas antes de la próxima visita.","correcta":false,"retro":"Cerrar sin investigar oculta el problema. La autoridad y los auditores revisan la calidad de las investigaciones, no solo su estado."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción al curso: la calidad como sistema en la industria y los servicios farmacéuticos$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Evolución histórica de la calidad: de la inspección a la gestión total
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Separar lo bueno de lo malo ya no alcanzaba","texto":"A comienzos del siglo XX, en las fábricas la calidad era tarea de inspectores que separaban al final de la línea las piezas buenas de las defectuosas. Funcionaba mientras la producción era pequeña. Cuando las fábricas crecieron, inspeccionar todo se volvió caro e insuficiente: los defectos ya estaban hechos y había que desecharlos. Cada etapa de la historia de la calidad nació de un problema así, y entenderlas te ayuda a reconocer en qué etapa está hoy tu propia organización."},"objetivos":["Describir las etapas de la evolución de la calidad: inspección, control estadístico, aseguramiento, calidad total y gestión de la calidad.","Relacionar cada etapa con el problema que intentaba resolver y con sus límites.","Identificar cómo esa evolución llegó a las BPM y a los sistemas de calidad farmacéuticos."],"conceptos":[{"icono":"Eye","termino":"Inspección","definicion":"Verificar el producto terminado y separar lo conforme de lo no conforme. Detecta defectos, pero no los previene."},{"icono":"LineChart","termino":"Control estadístico de procesos","definicion":"Uso de muestreo y gráficos de control para distinguir la variación normal de un proceso de las causas especiales que hay que corregir."},{"icono":"ShieldCheck","termino":"Aseguramiento de la calidad","definicion":"Conjunto de actividades planificadas y documentadas para dar confianza de que se cumplirán los requisitos antes de que el producto exista."},{"icono":"Users","termino":"Calidad total","definicion":"Enfoque en el que la calidad es responsabilidad de toda la organización, no solo de un departamento, y se orienta a la satisfacción del cliente y la mejora continua."}],"secciones":[{"titulo":"De la inspección al control estadístico","parrafos":["En la etapa de **inspección**, la calidad era un filtro al final del proceso. El problema es que un defecto detectado ya costó materiales, tiempo y trabajo, y la inspección al cien por ciento se cansa y se equivoca. En los años veinte, Walter Shewhart, en los laboratorios Bell, propuso mirar el **proceso** en lugar del producto: con muestras periódicas y **gráficos de control** se podía distinguir la variación propia del proceso de las causas especiales que lo sacan de control. Por primera vez la calidad se gestionaba antes de que el defecto llegara al final de la línea.","El **control estadístico** se expandió durante la Segunda Guerra Mundial con los planes de muestreo para compras militares. Su aporte sigue vigente en la industria farmacéutica: los controles en proceso, las tendencias de resultados analíticos, la revisión anual de producto y la verificación continuada del proceso son herederos directos de esa idea."]},{"titulo":"Del aseguramiento a la gestión total","parrafos":["Después de la guerra apareció el **aseguramiento de la calidad**: si se planifica, se documenta y se controla cada actividad que influye en la calidad, se puede dar confianza de que el producto cumplirá antes de fabricarlo. Las normas de proveedores de los sectores militar y nuclear exigían manuales, procedimientos y registros. Esa lógica es la base de las BPM: procedimientos escritos, personal capacitado, registros de cada operación y una función de calidad independiente de producción.","En Japón, con el aporte de Deming, Juran e Ishikawa, y en Estados Unidos con Feigenbaum, la calidad pasó a ser **responsabilidad de toda la organización**: la **calidad total**. Ya no bastaba con que un departamento controlara; la dirección, las compras, el diseño y cada operario participaban en la mejora continua. En 1987 se publicó la primera serie de normas **ISO 9000**, que llevó esos principios a un modelo de sistema certificable; su versión vigente es la de 2015."]},{"titulo":"Cómo llegó al medicamento","parrafos":["La industria farmacéutica recorrió el mismo camino empujada por tragedias. En 1937, en Estados Unidos, el elixir de sulfanilamida preparado con dietilenglicol causó más de cien muertes y llevó a exigir pruebas de seguridad antes de comercializar. A comienzos de los sesenta, la talidomida mostró que los efectos de un medicamento debían estudiarse a fondo. De esas crisis nacieron las exigencias de eficacia y seguridad, y las **Buenas Prácticas de Manufactura**: la Organización Mundial de la Salud publicó sus primeras BPM a finales de los años sesenta.","Hoy el sector está en la etapa de **gestión**: ICH Q10 (2008) describe un sistema de calidad farmacéutico para todo el ciclo de vida, apoyado en la gestión de riesgos (ICH Q9) y del conocimiento. La lección histórica es clara: cada etapa no reemplaza a la anterior, la contiene. Un laboratorio moderno sigue inspeccionando y usando estadística, pero dentro de un sistema que previene y aprende."]}],"errores":[{"error":"Pensar que las etapas modernas eliminan la inspección.","correccion":"La inspección sigue existiendo como verificación, pero ya no es la única defensa: el control del proceso previene."},{"error":"Usar el control estadístico solo para reportar, sin reaccionar a las señales.","correccion":"Un gráfico de control sirve si se define qué hacer ante una tendencia o un punto fuera de control."},{"error":"Creer que la calidad total es un programa de motivación.","correccion":"Es un modelo de gestión: liderazgo, procesos, datos y mejora continua en toda la organización."}],"comprueba":[{"pregunta":"¿Qué aportó Shewhart a la calidad?","respuesta":"Mirar el proceso con muestreo y gráficos de control para distinguir la variación común de las causas especiales."},{"pregunta":"¿Qué tienen en común el aseguramiento de la calidad y las BPM?","respuesta":"Ambos planifican, documentan y controlan las actividades que influyen en la calidad para dar confianza antes de producir."},{"pregunta":"¿Qué tragedia de 1937 marcó la regulación de medicamentos?","respuesta":"El elixir de sulfanilamida con dietilenglicol, que causó más de cien muertes en Estados Unidos."}],"resumen":["La calidad pasó de **detectar** defectos a **prevenirlos** y a **gestionarlos** en toda la organización.","Cada etapa **contiene** a la anterior: inspección, estadística, aseguramiento, calidad total y gestión.","En farmacia, las **tragedias** impulsaron las BPM y hoy ICH Q10 integra la gestión del ciclo de vida."],"referencias":[{"cita":"FDA. Ballentine C. Taste of raspberries, taste of death: the 1937 Elixir Sulfanilamide incident. FDA Consumer; 1981.","url":"https://www.fda.gov/files/about%20fda/published/The-Sulfanilamide-Disaster.pdf"},{"cita":"ISO. ISO 9000:2015 Sistemas de gestión de la calidad — Fundamentos y vocabulario.","url":"https://www.iso.org/standard/45481.html"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"En la sección de inspección y control estadístico","descripcion":"Línea del tiempo ilustrada con cinco etapas de la calidad, de la inspección a la gestión, con hitos farmacéuticos (1937, años sesenta, 1987, 2008).","alt":"Línea del tiempo de la evolución de la calidad hasta los sistemas farmacéuticos"}],"keywords":["historia de la calidad","evolución de la calidad etapas","de la inspección a la calidad total","control estadístico de procesos shewhart","historia de las bpm","aseguramiento de la calidad origen"],"mapa":{"centro":"De detectar a prevenir","ramas":[{"titulo":"Inspección","icono":"Eye","nodos":["Separar al final de la línea","Detecta, no previene","Costosa a gran escala"]},{"titulo":"Control estadístico","icono":"LineChart","nodos":["Shewhart y los gráficos de control","Muestreo","Variación común y especial"]},{"titulo":"Aseguramiento","icono":"ShieldCheck","nodos":["Planificar y documentar","Normas de proveedores","Confianza antes de producir"]},{"titulo":"Calidad total y gestión","icono":"Users","nodos":["Toda la organización","Mejora continua","Normas ISO 9000 desde 1987"]}]},"caso":{"titulo":"Más inspectores para menos quejas","contexto":"Una planta de empaque recibe quejas por estuches con el lote mal impreso. La primera propuesta del jefe de producción es agregar dos inspectores al final de la línea para revisar cada estuche.","pregunta":"¿En qué etapa histórica de la calidad se ubica esa propuesta y cuál sería un enfoque más maduro?","opciones":[{"texto":"Es aseguramiento; la propuesta es suficiente.","correcta":false,"retro":"Agregar inspectores al final es la etapa de inspección: detecta, pero no evita que el defecto se produzca."},{"texto":"Es inspección; lo maduro es controlar el proceso de impresión (verificación al inicio, controles periódicos, sistema de visión y análisis de la causa) para prevenir el defecto.","correcta":true,"retro":"El enfoque moderno ataca la causa y controla el proceso. La inspección puede quedar como verificación, no como la única defensa."},{"texto":"Es calidad total, porque involucra a más personas.","correcta":false,"retro":"La calidad total no consiste en sumar inspectores, sino en que toda la organización prevenga y mejore."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Evolución histórica de la calidad: de la inspección a la gestión total$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Evolución histórica de la calidad: de la inspección a la gestión total$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 03. Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Tres ideas que todavía se discuten en una revisión por la dirección","texto":"En una reunión de calidad, alguien propone premiar al área con menos desviaciones reportadas. Otra persona advierte que eso solo hará que se reporten menos. Una tercera pregunta cuánto cuestan los reprocesos del último año. Sin saberlo, están discutiendo a Deming, que alertó contra las metas que ocultan problemas; a Juran, que habló de planificar, controlar y mejorar; y a Crosby, que mostró que la falta de calidad tiene un precio. Sus ideas tienen setenta años y siguen resolviendo problemas de hoy."},"objetivos":["Explicar los aportes centrales de Deming, Juran y Crosby.","Aplicar esas ideas a situaciones de una planta o un servicio farmacéutico.","Reconocer en ICH Q10 e ISO 9001 los conceptos que vienen de estos autores."],"conceptos":[{"icono":"RefreshCw","termino":"Ciclo de Deming","definicion":"Planificar, hacer, estudiar o verificar y actuar: el ciclo de mejora que Deming difundió a partir de las ideas de Shewhart y que ISO 9001 adopta como PHVA."},{"icono":"Layers","termino":"Trilogía de Juran","definicion":"Tres procesos de gestión: planificación de la calidad, control de la calidad y mejora de la calidad."},{"icono":"Target","termino":"Cero defectos","definicion":"Idea de Crosby según la cual el estándar de desempeño es hacerlo bien desde la primera vez, no un nivel «aceptable» de errores."},{"icono":"Calculator","termino":"Costo de la no calidad","definicion":"Lo que cuesta hacer las cosas mal: reprocesos, rechazos, investigaciones, quejas, retiros del mercado y pérdida de confianza."}],"secciones":[{"titulo":"W. Edwards Deming: el sistema y la dirección","parrafos":["Deming enseñó control estadístico en Japón desde 1950 y es recordado por dos ideas. La primera: la mayoría de los problemas de calidad vienen del **sistema** y no de las personas; culpar al operario sin cambiar el proceso no resuelve nada. La segunda: la mejora es un **ciclo** de planificar, hacer, estudiar y actuar. En su libro *Out of the Crisis* (1986) resumió su filosofía en **14 puntos** para la dirección, entre ellos crear constancia en el propósito de mejora, eliminar el miedo, romper las barreras entre departamentos y abandonar las metas numéricas que no vienen acompañadas de un método para lograrlas.","En una planta farmacéutica, la idea de Deming aparece cuando una investigación de desviación concluye «error humano» sin preguntar por qué el sistema permitió el error. ICH Q10 recoge su espíritu al pedir que la dirección promueva la mejora continua y que las investigaciones busquen la causa raíz."]},{"titulo":"Joseph Juran: planificar, controlar y mejorar","parrafos":["Juran definió la calidad como **adecuación al uso** y propuso la **trilogía**: planificar la calidad (identificar a los clientes y sus necesidades, y diseñar procesos capaces de cumplirlas), controlarla (medir, comparar con la meta y actuar sobre las diferencias) y mejorarla (proyecto por proyecto, atacando los problemas crónicos). También difundió el principio de Pareto en calidad: unas pocas causas explican la mayor parte de los problemas.","La trilogía se reconoce en el ciclo de vida de ICH Q10: el desarrollo planifica la calidad, la fabricación la controla con la estrategia de control y la revisión del desempeño la mejora. Cuando un laboratorio prioriza sus CAPA por el impacto en el paciente y en el volumen de desviaciones, está aplicando a Juran."]},{"titulo":"Philip Crosby: cero defectos y el precio del incumplimiento","parrafos":["Crosby, en *Quality is Free* (1979), sostuvo que la calidad es **cumplir los requisitos**, que el sistema debe basarse en la **prevención**, que el estándar es **cero defectos** y que la calidad se mide por el **precio del incumplimiento**. Su mensaje para la dirección fue práctico: la calidad no cuesta, lo que cuesta es no tenerla.","En farmacia, el costo de la no calidad incluye lotes rechazados, reprocesos, investigaciones largas, análisis repetidos, quejas, retiros del mercado y sanciones. Cuantificarlo en la revisión por la dirección convierte la calidad en una decisión de negocio y ayuda a justificar inversiones preventivas, como la calificación de un equipo o la capacitación de un turno."]}],"errores":[{"error":"Cerrar investigaciones con «error humano» sin preguntar por qué el proceso lo permitió.","correccion":"Aplica a Deming: busca la causa en el sistema (procedimiento, diseño, capacitación, carga de trabajo)."},{"error":"Atacar todos los problemas a la vez.","correccion":"Aplica a Juran: prioriza con Pareto y trabaja proyecto por proyecto."},{"error":"Presentar la calidad como un gasto.","correccion":"Aplica a Crosby: cuantifica el costo de la no calidad y muestra el retorno de la prevención."}],"comprueba":[{"pregunta":"¿Cuáles son los tres procesos de la trilogía de Juran?","respuesta":"Planificación, control y mejora de la calidad."},{"pregunta":"¿Qué entiende Crosby por calidad?","respuesta":"Cumplir los requisitos, con un sistema de prevención, estándar de cero defectos y medición por el precio del incumplimiento."},{"pregunta":"¿Qué dice Deming sobre el origen de la mayoría de los problemas?","respuesta":"Que vienen del sistema y no de las personas, por lo que hay que mejorar el proceso en lugar de culpar al operario."}],"resumen":["**Deming**: el sistema causa la mayoría de los problemas; mejora con el ciclo PHVA y sin miedo.","**Juran**: la calidad se planifica, se controla y se mejora proyecto por proyecto.","**Crosby**: cumplir requisitos desde la primera vez y medir el **costo de la no calidad**."],"referencias":[{"cita":"Deming WE. Out of the crisis. Cambridge (MA): MIT Center for Advanced Engineering Study; 1986.","url":""},{"cita":"Juran JM, De Feo JA. Juran's quality handbook: the complete guide to performance excellence. 7.ª ed. Nueva York: McGraw-Hill; 2016.","url":""},{"cita":"Crosby PB. Quality is free: the art of making quality certain. Nueva York: McGraw-Hill; 1979.","url":""},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Tres tarjetas ilustradas con la idea central de cada autor (ciclo, trilogía y cero defectos), sin retratos, en la paleta de Edvanta.","alt":"Ideas centrales de Deming, Juran y Crosby sobre la calidad"}],"keywords":["deming juran crosby","aportes de deming a la calidad","trilogía de juran","cero defectos crosby","costo de la no calidad","14 puntos de deming","gurús de la calidad"],"mapa":{"centro":"Los grandes autores","ramas":[{"titulo":"Deming","icono":"RefreshCw","nodos":["Ciclo PHVA","14 puntos para la dirección","Variación y sistema"]},{"titulo":"Juran","icono":"Layers","nodos":["Trilogía: planificar, controlar, mejorar","Adecuación al uso","Proyecto de mejora"]},{"titulo":"Crosby","icono":"Target","nodos":["Cero defectos","Precio del incumplimiento","Calidad es cumplir requisitos"]},{"titulo":"En farmacia","icono":"Pill","nodos":["Mejora continua de ICH Q10","Revisión por la dirección","Costo de desviaciones y retiros"]}]},"caso":{"titulo":"El bono por menos desviaciones","contexto":"La gerencia de una planta propone un bono trimestral para los turnos que reporten menos desviaciones. Aseguramiento de calidad debe dar su concepto.","pregunta":"¿Qué concepto da aseguramiento, con base en los autores de la clase?","opciones":[{"texto":"Favorable: menos desviaciones significa más calidad.","correcta":false,"retro":"Deming advirtió que las metas numéricas sin método generan miedo y ocultamiento. El bono premia no reportar."},{"texto":"Desfavorable: incentiva ocultar desviaciones. Mejor medir la calidad de las investigaciones, la eficacia de las CAPA y el costo de la no calidad.","correcta":true,"retro":"Es la lectura de Deming (eliminar el miedo) y de Crosby (medir el precio del incumplimiento). Un sistema sano reporta más y repite menos."},{"texto":"Favorable si se acompaña de sanciones a quien cometa errores.","correcta":false,"retro":"Las sanciones refuerzan el miedo y el subregistro. El foco debe estar en el sistema, no en culpar a las personas."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 04. Calidad del medicamento: por qué la industria farmacéutica requiere un sistema propio
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El paciente no puede comprobar lo que toma","texto":"Quien compra un televisor puede encenderlo y ver si funciona. Quien recibe un jarabe para su hijo no tiene forma de saber si contiene la cantidad correcta de principio activo, si el excipiente es el declarado o si está contaminado. En 2022, la OMS alertó sobre jarabes pediátricos contaminados con dietilenglicol y etilenglicol asociados a muertes de niños en Gambia. El paciente confía porque no puede verificar. Esa asimetría es la razón por la que el medicamento exige un sistema de calidad más estricto que casi cualquier otro producto."},"objetivos":["Explicar por qué la calidad del medicamento no puede verificarse por el usuario ni garantizarse solo con el análisis final.","Describir los atributos de calidad de un medicamento: identidad, pureza, potencia, seguridad y desempeño.","Relacionar esas características con los elementos de las BPM y del sistema de calidad farmacéutico."],"conceptos":[{"icono":"Pill","termino":"Atributos de calidad","definicion":"Las propiedades que el medicamento debe cumplir: identidad (es lo que dice ser), pureza (sin contaminantes ni impurezas fuera de límite), potencia o valoración (la cantidad declarada), seguridad y desempeño (por ejemplo, disolución y estabilidad durante la vida útil)."},{"icono":"Microscope","termino":"Análisis destructivo y por muestreo","definicion":"La mayoría de los ensayos destruyen la unidad analizada y se hacen sobre una muestra; por eso no pueden demostrar por sí solos la calidad de cada unidad del lote."},{"icono":"BadgeCheck","termino":"Liberación del lote","definicion":"La decisión documentada, tomada por una persona autorizada e independiente de producción, de que el lote cumple su registro sanitario y se fabricó bajo BPM."},{"icono":"Stamp","termino":"Registro sanitario","definicion":"La autorización del INVIMA que fija la fórmula, las especificaciones, el fabricante y las condiciones con las que el medicamento puede comercializarse."}],"secciones":[{"titulo":"Un producto distinto","parrafos":["El medicamento tiene tres rasgos que justifican un sistema propio. Primero, el **usuario no puede evaluar su calidad**: ni el paciente ni, muchas veces, el profesional de la salud pueden distinguir a simple vista un medicamento subestándar. Segundo, las **consecuencias de una falla son graves**: un error de dosis, una contaminación cruzada o un excipiente adulterado pueden causar daño o muerte. Tercero, **la calidad no se puede comprobar del todo en el producto terminado**: la uniformidad de contenido, la esterilidad o la ausencia de contaminación cruzada dependen de cómo se fabricó.","Por eso la regulación no solo autoriza el producto con un registro sanitario, sino que exige que se fabrique bajo **Buenas Prácticas de Manufactura** certificadas por la autoridad, que cada lote sea liberado por una persona autorizada y que exista vigilancia después de la comercialización (farmacovigilancia, quejas, retiros del mercado)."]},{"titulo":"Lo que la historia enseñó","parrafos":["El caso del elixir de sulfanilamida en 1937 y la alerta de la OMS de 2022 por jarabes contaminados con dietilenglicol tienen un mismo origen: un excipiente que nadie controló. La lección se tradujo en requisitos concretos de las BPM: calificar a los proveedores, analizar cada lote de materia prima antes de usarla, mantener la trazabilidad y controlar los cambios. La OMS insiste en que la contaminación de excipientes sigue siendo un riesgo vigente en el mundo.","Otros riesgos propios del medicamento son la **contaminación cruzada** entre productos fabricados en las mismas instalaciones, las **mezclas** de etiquetas o lotes y la **degradación** durante la vida útil. Cada uno tiene en las BPM un control específico: segregación y limpieza validada, despeje de línea y conciliación de material impreso, y estudios de estabilidad."]},{"titulo":"Del cumplimiento al sistema","parrafos":["Cumplir BPM es obligatorio, pero un conjunto de requisitos aislados no garantiza que funcionen juntos. Un **sistema de calidad farmacéutico** conecta los controles: el cambio de proveedor activa el control de cambios, que activa la calificación, que se refleja en la especificación y en la capacitación; la queja de un paciente activa una investigación que puede terminar en una CAPA y en una revisión del proceso. ICH Q10 llama a esto gestionar el conocimiento y el ciclo de vida del producto.","En el servicio farmacéutico la lógica es la misma: la Resolución 1403 de 2007 exige procesos documentados de selección, adquisición, recepción, almacenamiento, distribución y dispensación, porque la calidad que el fabricante construyó se puede perder en un almacenamiento a mala temperatura o en una dispensación equivocada."]}],"errores":[{"error":"Confiar en el certificado de análisis del proveedor sin verificación propia.","correccion":"Califica al proveedor y realiza al menos el ensayo de identidad de cada lote; para excipientes de riesgo, los ensayos críticos de pureza."},{"error":"Pensar que el análisis final compensa un proceso descontrolado.","correccion":"La calidad se construye en el proceso; el análisis la confirma sobre una muestra."},{"error":"Olvidar la cadena de distribución y dispensación.","correccion":"Incluye almacenamiento, transporte y dispensación en el sistema de calidad."}],"comprueba":[{"pregunta":"¿Por qué el paciente no puede juzgar la calidad del medicamento?","respuesta":"Porque los atributos críticos (contenido, pureza, contaminación, disolución) no son visibles y requieren análisis de laboratorio."},{"pregunta":"¿Qué lección comparten el caso de 1937 y la alerta de la OMS de 2022?","respuesta":"Que un excipiente no controlado (dietilenglicol) puede causar muertes; de ahí la exigencia de calificar proveedores y analizar materias primas."}],"resumen":["El usuario **no puede verificar** la calidad del medicamento: confía en el sistema.","La calidad depende de **cómo se fabricó**, no solo del análisis final.","BPM, liberación por persona autorizada y vigilancia forman un **sistema propio** del sector."],"referencias":[{"cita":"OMS. Medical Product Alert N.° 6/2022: medicamentos pediátricos subestándar (contaminados con dietilenglicol y etilenglicol).","url":"https://www.who.int/news/item/05-10-2022-medical-product-alert-n-6-2022-substandard-(contaminated)-paediatric-medicines"},{"cita":"FDA. Ballentine C. Taste of raspberries, taste of death: the 1937 Elixir Sulfanilamide incident. FDA Consumer; 1981.","url":"https://www.fda.gov/files/about%20fda/published/The-Sulfanilamide-Disaster.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"INVIMA. Decreto 677 de 1995: régimen de registros y licencias, control de calidad y vigilancia sanitaria de medicamentos.","url":"https://www.invima.gov.co/biblioteca/decreto_677_1995_0pdf"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Cadena ilustrada del medicamento desde el desarrollo hasta el paciente, con un escudo de calidad en cada eslabón.","alt":"Cadena de calidad del medicamento desde el desarrollo hasta la dispensación"}],"keywords":["calidad del medicamento","atributos de calidad de un medicamento","por qué las bpm son obligatorias","dietilenglicol jarabes oms","liberación de lotes farmacéuticos","sistema de calidad farmacéutico"],"proceso":{"titulo":"Dónde se construye la calidad de un medicamento","intro":"Cada eslabón puede ganar o perder la calidad que el paciente no puede verificar.","pasos":[{"titulo":"Desarrollo","detalle":"Se define la fórmula, el proceso y las especificaciones que el INVIMA aprueba en el registro sanitario.","icono":"FlaskConical","evidencia":"Expediente y registro sanitario."},{"titulo":"Proveedores y materiales","detalle":"Se califican proveedores y se analiza cada lote de materia prima antes de usarlo.","icono":"Package","evidencia":"Proveedores aprobados y certificados de análisis verificados."},{"titulo":"Fabricación bajo BPM","detalle":"Procesos validados, personal capacitado, áreas y equipos calificados y registros de lote.","icono":"Factory","evidencia":"Registro de lote completo."},{"titulo":"Control y liberación","detalle":"Análisis según especificaciones y revisión del registro de lote antes de liberar.","icono":"BadgeCheck","evidencia":"Certificado de análisis y liberación firmada."},{"titulo":"Distribución y dispensación","detalle":"Almacenamiento y transporte en condiciones controladas; dispensación correcta.","icono":"Truck","evidencia":"Registros de temperatura y dispensación."},{"titulo":"Vigilancia","detalle":"Quejas, farmacovigilancia y retiros del mercado cierran el ciclo.","icono":"Eye","evidencia":"Investigaciones y reportes."}]},"caso":{"titulo":"El excipiente más barato","contexto":"Compras propone cambiar el proveedor de propilenglicol de un jarabe por uno nuevo que ofrece mejor precio y entrega un certificado de análisis que cumple la farmacopea.","pregunta":"¿Qué debe exigir el sistema de calidad antes de usar el nuevo proveedor?","opciones":[{"texto":"Aceptarlo: el certificado de análisis demuestra que cumple.","correcta":false,"retro":"Un certificado no reemplaza la calificación del proveedor ni el análisis propio. Los casos de dietilenglicol ocurrieron con excipientes que «tenían papeles»."},{"texto":"Gestionar el cambio: calificar al proveedor, analizar los lotes incluido el ensayo de dietilenglicol y etilenglicol, evaluar el impacto en el registro y aprobar antes de usar.","correcta":true,"retro":"Es el sistema funcionando: control de cambios, calificación de proveedores y análisis de identidad y pureza antes del uso."},{"texto":"Usarlo en un lote y analizar el producto terminado.","correcta":false,"retro":"Probar con el producto terminado expone al paciente al riesgo. La verificación debe hacerse antes de fabricar."}]}}$j$::jsonb;
