  END IF;

  -- 11. Principios generales de BPM de la OMS y el sistema de calidad farmacéutico
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Las BPM no son una lista de chequeo","texto":"Un auditor nuevo recorre una planta con una lista de 300 preguntas y concluye que «casi todo cumple». Una auditora con experiencia recorre la misma planta y pregunta: ¿cómo sabe la dirección que el sistema funciona?, ¿quién decide liberar un lote y con qué información?, ¿qué pasó con las desviaciones del último trimestre? Las BPM de la OMS empiezan por el sistema de calidad, no por la lista. Esta clase muestra por qué."},"objetivos":["Describir la estructura de los principios principales de BPM de la OMS.","Explicar la relación entre el sistema de calidad farmacéutico, las BPM y el control de calidad.","Identificar los elementos del sistema de calidad que la OMS incorporó a partir de ICH Q10 y Q9."],"conceptos":[{"icono":"Layers","termino":"Sistema de calidad farmacéutico","definicion":"El sistema de gestión que dirige y controla a la empresa en lo relativo a la calidad. Contiene a las BPM, que a su vez contienen al control de calidad."},{"icono":"Factory","termino":"Buenas Prácticas de Manufactura","definicion":"La parte de la gestión de calidad que asegura que los productos se fabrican y controlan de forma consistente según los estándares apropiados para su uso y lo exigido en su autorización."},{"icono":"Microscope","termino":"Control de calidad","definicion":"La parte de las BPM que se ocupa del muestreo, las especificaciones, los análisis y la liberación."},{"icono":"FileCheck","termino":"Revisión de calidad del producto","definicion":"Revisión periódica, generalmente anual, de todos los lotes de un producto para verificar la consistencia del proceso, detectar tendencias y decidir mejoras."}],"secciones":[{"titulo":"Tres círculos concéntricos","parrafos":["Los principios principales de BPM de la OMS (TRS 986, Anexo 2) ordenan la calidad en tres niveles que se contienen. El más amplio es el **sistema de calidad farmacéutico**: la dirección, la política, los recursos, la gestión de riesgos, la revisión por la dirección. Dentro están las **BPM**: los requisitos de fabricación y control. Y dentro de las BPM está el **control de calidad**: muestreo, especificaciones, análisis y liberación. Confundir los niveles lleva a creer que un buen laboratorio de análisis equivale a un buen sistema de calidad.","La guía detalla luego los elementos: saneamiento e higiene; calificación y validación; quejas; retiros del mercado; producción y análisis por contrato; autoinspección, auditorías de calidad y de proveedores; personal y capacitación; higiene del personal; instalaciones; equipos; materiales; documentación; buenas prácticas de producción y buenas prácticas de control de calidad."]},{"titulo":"Lo que la OMS tomó de ICH","parrafos":["En su actualización de 2014, la OMS incorporó explícitamente conceptos de **ICH Q10** y **Q9**: la responsabilidad de la dirección en el sistema de calidad, la **gestión de riesgos para la calidad** como base de las decisiones, la **revisión de calidad del producto** y la mejora continua a lo largo del ciclo de vida. Así, las BPM dejaron de ser solo un conjunto de reglas de fabricación y pasaron a exigir un sistema que se mide y mejora.","La revisión de calidad del producto es un buen ejemplo: obliga a mirar todos los lotes del año, las desviaciones, los cambios, los resultados fuera de especificación, las quejas, los retiros y la estabilidad, y a concluir si el proceso sigue bajo control o necesita mejoras. Es la versión farmacéutica del ciclo PHVA aplicada a cada producto."]},{"titulo":"Cómo se conecta con la norma colombiana","parrafos":["Los manuales de la Resolución 1160 de 2016 se basan en informes anteriores de la OMS (Informe 37 e Informe 45), que ya planteaban el sistema de garantía de calidad como base. Las versiones posteriores de la OMS no cambian la obligación colombiana, pero sí muestran hacia dónde evoluciona la expectativa de las autoridades: más gestión de riesgos, más datos de desempeño y más responsabilidad de la dirección.","Para quien diseña un SGC, la recomendación práctica es cumplir la norma adoptada y usar la guía más reciente como **referencia de buenas prácticas**, especialmente en gestión de riesgos, revisión de producto e integridad de datos."]}],"errores":[{"error":"Igualar calidad con control de calidad.","correccion":"El control de calidad es una parte de las BPM, que son una parte del sistema de calidad."},{"error":"Hacer la revisión anual de producto como un trámite de recopilación.","correccion":"Úsala para concluir sobre el control del proceso y decidir mejoras con responsables."}],"comprueba":[{"pregunta":"¿Cuáles son los tres niveles que plantea la OMS?","respuesta":"Sistema de calidad farmacéutico, BPM y control de calidad, en ese orden de amplitud."},{"pregunta":"¿Qué revisa la revisión de calidad del producto?","respuesta":"Todos los lotes del periodo, desviaciones, cambios, resultados fuera de especificación, quejas, retiros y estabilidad, para concluir sobre el control del proceso."}],"resumen":["Sistema de calidad ⊃ **BPM** ⊃ **control de calidad**.","La OMS incorporó **ICH Q10 y Q9**: dirección, riesgos y revisión de producto.","Cumple la norma adoptada y usa la guía reciente como **referencia**."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ICH. Q9(R1) Quality Risk Management (2023).","url":"https://database.ich.org/sites/default/files/ICH_Q9%28R1%29_Guideline_Step4_2023_0126_0.pdf"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"}],"imagenes":[{"ubicacion":"En la sección de los tres círculos","descripcion":"Tres círculos concéntricos rotulados: sistema de calidad farmacéutico, BPM y control de calidad.","alt":"Relación entre sistema de calidad, BPM y control de calidad según la OMS"}],"keywords":["principios bpm oms","trs 986 anexo 2","sistema de calidad farmacéutico oms","diferencia entre bpm y control de calidad","revisión anual de producto","gmp oms principios principales"],"mapa":{"centro":"BPM de la OMS","ramas":[{"titulo":"Sistema","icono":"Layers","nodos":["Sistema de calidad farmacéutico","Gestión de riesgos","Revisión de calidad del producto"]},{"titulo":"Recursos","icono":"Users","nodos":["Personal y capacitación","Higiene","Instalaciones y equipos"]},{"titulo":"Operación","icono":"Factory","nodos":["Materiales","Documentación","Producción y control de calidad"]},{"titulo":"Vigilancia","icono":"Eye","nodos":["Quejas y retiros","Contratos","Autoinspección y auditorías"]}]},"caso":{"titulo":"El laboratorio impecable y el sistema débil","contexto":"Una planta tiene un laboratorio de control de calidad con equipos modernos y métodos validados. Sin embargo, no hace revisión anual de producto, la dirección no revisa indicadores de calidad y las desviaciones se cierran sin tendencias.","pregunta":"¿Cuál es el diagnóstico correcto según los principios de la OMS?","opciones":[{"texto":"La planta cumple porque el control de calidad es robusto.","correcta":false,"retro":"El control de calidad es solo el círculo interno; faltan elementos del sistema de calidad farmacéutico."},{"texto":"Hay brechas en el sistema de calidad farmacéutico: revisión de calidad del producto, revisión por la dirección y análisis de tendencias.","correcta":true,"retro":"Los principios de la OMS exigen que el sistema se mida y se revise; un buen laboratorio no lo reemplaza."},{"texto":"Basta con comprar más equipos de análisis.","correcta":false,"retro":"Más análisis no resuelve la falta de gestión del sistema."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Principios generales de BPM de la OMS y el sistema de calidad farmacéutico$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Principios generales de BPM de la OMS y el sistema de calidad farmacéutico$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 12. Servicio farmacéutico en el Decreto 780 de 2016 y Decreto 2200 de 2005
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La calidad no termina en la planta","texto":"Un medicamento fabricado bajo BPM puede perder su calidad en pocas horas si se almacena junto a una ventana al sol, si una cadena de frío se rompe o si se dispensa el producto equivocado. Por eso Colombia regula el servicio farmacéutico con el mismo enfoque de procesos que la industria: el Decreto 2200 de 2005, hoy compilado en el Decreto 780 de 2016, definió qué es el servicio, qué procesos debe tener y quién responde por ellos."},"objetivos":["Explicar qué es el servicio farmacéutico y sus modalidades según la normativa colombiana.","Describir los procesos generales y especiales del servicio farmacéutico.","Relacionar esos procesos con un sistema de gestión de calidad."],"conceptos":[{"icono":"Pill","termino":"Servicio farmacéutico","definicion":"El servicio de atención en salud responsable de las actividades, procedimientos e intervenciones de carácter técnico, científico y administrativo relacionados con los medicamentos y los dispositivos médicos, para contribuir a la salud y la calidad de vida."},{"icono":"Building2","termino":"Dependiente e independiente","definicion":"El servicio farmacéutico dependiente hace parte de una institución prestadora de servicios de salud; el independiente se presta en establecimientos farmacéuticos como droguerías y farmacias-droguerías."},{"icono":"Workflow","termino":"Procesos generales","definicion":"Los procesos que todo servicio debe cumplir según su complejidad, como selección, adquisición, recepción y almacenamiento, distribución y dispensación de medicamentos."},{"icono":"Sparkles","termino":"Procesos especiales","definicion":"Los que se suman según el tipo y la complejidad del servicio, como la atención farmacéutica, la elaboración de preparaciones magistrales o la participación en programas de farmacovigilancia."}],"secciones":[{"titulo":"Del Decreto 2200 al Decreto 780","parrafos":["El **Decreto 2200 de 2005** reglamentó el servicio farmacéutico en Colombia y estableció sus objetivos, principios, modalidades, procesos y responsables. En 2016, el Gobierno expidió el **Decreto 780**, Decreto Único Reglamentario del sector salud, que compiló en un solo cuerpo normativo muchos decretos del sector, entre ellos las disposiciones del servicio farmacéutico. Por eso hoy se cita el Decreto 780 de 2016, y el 2200 de 2005 se sigue consultando para entender el origen y la estructura del texto.","La norma distingue el servicio **dependiente**, que hace parte de una institución prestadora de servicios de salud (por ejemplo, el servicio farmacéutico de un hospital), y el **independiente**, que se presta en establecimientos farmacéuticos como droguerías. También define grados de complejidad del servicio, de los que dependen los procesos exigidos y el perfil de quien ejerce la dirección técnica."]},{"titulo":"Los procesos del servicio","parrafos":["Los **procesos generales** recorren la vida del medicamento dentro del servicio: **selección** (qué medicamentos tener, con criterios de eficacia, seguridad y costo), **adquisición**, **recepción técnica** y **almacenamiento** en condiciones que conserven la calidad, **distribución** y **dispensación**, junto con el manejo de devoluciones y la destrucción o desnaturalización de medicamentos. Cada uno debe estar documentado en procedimientos y tener registros.","Los **procesos especiales** dependen del tipo y la complejidad del servicio: la **atención farmacéutica** al paciente, la elaboración de **preparaciones magistrales** y otras preparaciones, la participación en **farmacovigilancia** y en comités, y actividades de información y educación sobre el uso adecuado de los medicamentos."]},{"titulo":"Por qué es un sistema de calidad","parrafos":["La norma no se limita a enumerar tareas: exige que el servicio tenga procesos documentados, responsables, registros y seguimiento. Entre sus principios están la **conservación de la calidad** de los medicamentos, la **oportunidad**, la **seguridad** y la **eficiencia**. Esto es, en esencia, un sistema de gestión de calidad aplicado al servicio, que la Resolución 1403 de 2007 desarrolla con el modelo de gestión y el manual de condiciones esenciales que estudiarás en la siguiente clase.","Para quien dirige un servicio farmacéutico, la tarea es convertir estos procesos en un mapa de procesos con indicadores (por ejemplo, oportunidad en la dispensación, errores de dispensación, rotura de cadena de frío, vencidos), auditarlos y mejorarlos, igual que en una planta."]}],"errores":[{"error":"Citar solo el Decreto 2200 de 2005 como norma vigente.","correccion":"Cita el Decreto 780 de 2016, que compila sus disposiciones, y usa el 2200 para entender la estructura."},{"error":"Procesos del servicio sin indicadores.","correccion":"Define al menos un indicador por proceso crítico y revísalo periódicamente."},{"error":"Tratar las excursiones de temperatura como un problema técnico de la nevera.","correccion":"Gestiónalas como no conformidades con evaluación del producto, decisión documentada y acción correctiva."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre servicio dependiente e independiente?","respuesta":"El dependiente hace parte de una institución prestadora de servicios de salud; el independiente se presta en establecimientos farmacéuticos."},{"pregunta":"Nombra cuatro procesos generales del servicio farmacéutico.","respuesta":"Selección, adquisición, recepción y almacenamiento, distribución y dispensación."}],"resumen":["El servicio farmacéutico se rige por el **Decreto 780 de 2016**, que compila el **Decreto 2200 de 2005**.","Tiene **procesos generales** y **procesos especiales** según su tipo y complejidad.","Es, en esencia, un **sistema de calidad**: procesos, responsables, registros e indicadores."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Decreto 780 de 2016, Decreto Único Reglamentario del sector salud.","url":"https://minsalud.gov.co/Normativa/Paginas/decreto-unico-minsalud-780-de-2016.aspx"},{"cita":"Presidencia de la República. Decreto 2200 de 2005: reglamenta el servicio farmacéutico.","url":"https://www.invima.gov.co/sites/default/files/Decreto-2200de-2005.pdf"},{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos.","url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Recorrido ilustrado del medicamento dentro de un servicio farmacéutico: selección, adquisición, recepción, almacenamiento, distribución y dispensación.","alt":"Procesos generales del servicio farmacéutico en Colombia"}],"keywords":["decreto 2200 de 2005","decreto 780 de 2016 servicio farmacéutico","servicio farmacéutico colombia","procesos del servicio farmacéutico","servicio farmacéutico dependiente e independiente","procesos especiales servicio farmacéutico"],"mapa":{"centro":"Servicio farmacéutico","ramas":[{"titulo":"Modalidades","icono":"Building2","nodos":["Dependiente (IPS)","Independiente (establecimientos)","Grados de complejidad"]},{"titulo":"Procesos generales","icono":"Workflow","nodos":["Selección y adquisición","Recepción y almacenamiento","Distribución y dispensación"]},{"titulo":"Procesos especiales","icono":"Sparkles","nodos":["Atención farmacéutica","Preparaciones magistrales","Farmacovigilancia"]},{"titulo":"Responsables","icono":"UserCheck","nodos":["Dirección técnica","Talento humano competente","Vigilancia de la secretaría de salud"]}]},"caso":{"titulo":"La nevera de la droguería","contexto":"En una droguería, la nevera de los productos de cadena de frío registra temperaturas fuera de rango durante un fin de semana. El lunes, el auxiliar reinicia la nevera y sigue dispensando insulinas.","pregunta":"¿Qué proceso falló y qué debió ocurrir?","opciones":[{"texto":"Ningún proceso: la nevera ya volvió a funcionar.","correcta":false,"retro":"La excursión de temperatura pudo afectar la calidad; seguir dispensando sin evaluar expone al paciente."},{"texto":"Falló el proceso de almacenamiento: debió aislarse el producto, documentar la excursión, evaluarla con el director técnico y el fabricante, y decidir antes de dispensar.","correcta":true,"retro":"Conservar la calidad es un principio del servicio farmacéutico; una excursión se trata como una no conformidad con su investigación."},{"texto":"Falló el proceso de selección.","correcta":false,"retro":"La selección define qué medicamentos tener; el problema está en el almacenamiento y la respuesta a la desviación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Servicio farmacéutico en el Decreto 780 de 2016 y Decreto 2200 de 2005$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Servicio farmacéutico en el Decreto 780 de 2016 y Decreto 2200 de 2005$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 13. Resolución 1403 de 2007: sistema de gestión de calidad del servicio farmacéutico
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Del procedimiento al modelo de gestión","texto":"Dos droguerías tienen los mismos procedimientos escritos. En la primera, nadie mide los errores de dispensación y los vencidos se descubren al hacer inventario. En la segunda, cada mes se revisan indicadores, se analizan las causas de los errores y se ajusta el procedimiento. Ambas «cumplen» en papel, pero solo la segunda tiene un sistema de gestión. La Resolución 1403 de 2007 pide lo segundo."},"objetivos":["Describir los dos componentes de la Resolución 1403 de 2007: el modelo de gestión y el manual de condiciones esenciales y procedimientos.","Identificar los elementos de un sistema de gestión de calidad del servicio farmacéutico.","Diseñar indicadores básicos para los procesos del servicio."],"conceptos":[{"icono":"Network","termino":"Modelo de gestión del servicio farmacéutico","definicion":"El marco que orienta al servicio hacia la calidad, el uso adecuado de los medicamentos y la mejora continua, con procesos planificados, ejecutados, verificados y mejorados."},{"icono":"ClipboardCheck","termino":"Condiciones esenciales","definicion":"Los requisitos mínimos de infraestructura, dotación, talento humano y procesos que debe cumplir el servicio farmacéutico para funcionar."},{"icono":"FileText","termino":"Procedimientos documentados","definicion":"La descripción escrita de cómo se ejecuta cada proceso del servicio, con responsables, registros y controles."},{"icono":"BarChart3","termino":"Indicadores de gestión","definicion":"Medidas periódicas del desempeño de los procesos que permiten decidir con datos y demostrar mejora."}],"secciones":[{"titulo":"Qué adopta la resolución","parrafos":["La **Resolución 1403 de 2007** del entonces Ministerio de la Protección Social adoptó el **Modelo de Gestión del Servicio Farmacéutico** y el **Manual de Condiciones Esenciales y Procedimientos**. El modelo plantea que el servicio debe gestionarse con un enfoque de calidad orientado al paciente y al uso adecuado de los medicamentos; el manual baja ese enfoque a requisitos concretos de infraestructura, dotación, talento humano y procedimientos para cada proceso.","La resolución exige que el servicio farmacéutico cuente con un **sistema de gestión de la calidad**: procesos documentados, responsables definidos, registros, seguimiento con indicadores y acciones de mejora. Es la base de lo que la secretaría de salud verifica en sus visitas, junto con las disposiciones del Decreto 780 de 2016."]},{"titulo":"Los procedimientos que no pueden faltar","parrafos":["El manual describe, para cada proceso, cómo debe hacerse: la **selección** con base en criterios técnicos; la **adquisición** a proveedores autorizados; la **recepción técnica** verificando documentos, cantidades, fecha de vencimiento, lote, registro sanitario y estado del producto; el **almacenamiento** con control de temperatura y humedad, rotación por fecha de vencimiento y separación de productos no conformes; la **distribución**; la **dispensación** con verificación de la prescripción e información al paciente; y la gestión de **devoluciones** y medicamentos vencidos o deteriorados.","Cada procedimiento debe generar **registros**: actas de recepción, planillas de temperatura y humedad, registros de dispensación, reportes de eventos adversos. Sin registros no hay forma de demostrar que el proceso se cumple ni de medirlo."]},{"titulo":"Medir para mejorar","parrafos":["Un SGC del servicio farmacéutico necesita pocos indicadores bien elegidos. Algunos ejemplos: porcentaje de **errores de dispensación** detectados; **oportunidad** en la entrega de medicamentos; **pendientes** por falta de inventario; **vencidos** como porcentaje del inventario; **excursiones de temperatura** de cadena de frío; reportes de **farmacovigilancia** gestionados. Cada indicador debe tener fórmula, meta, frecuencia, fuente de datos y responsable.","Los indicadores se revisan con la dirección, que decide acciones. Ese ciclo de medir, analizar, decidir y verificar es lo que convierte los procedimientos en un sistema y lo que diferencia a la droguería que gestiona de la que solo cumple en papel."]}],"errores":[{"error":"Procedimientos copiados de otra institución.","correccion":"Ajusta cada procedimiento a tu servicio real: tu infraestructura, tu personal y tus riesgos."},{"error":"Indicadores que se calculan pero nadie revisa.","correccion":"Define quién los revisa, con qué frecuencia y qué decisión se toma si no se cumple la meta."},{"error":"Recepción técnica limitada a contar cajas.","correccion":"Verifica documentos, registro sanitario, lote, vencimiento, condiciones de transporte y estado del producto."}],"comprueba":[{"pregunta":"¿Qué dos componentes adopta la Resolución 1403 de 2007?","respuesta":"El Modelo de Gestión del Servicio Farmacéutico y el Manual de Condiciones Esenciales y Procedimientos."},{"pregunta":"Da tres indicadores útiles para un servicio farmacéutico.","respuesta":"Por ejemplo: errores de dispensación, oportunidad en la entrega, vencidos, pendientes o excursiones de temperatura."}],"resumen":["La Resolución 1403 de 2007 adopta un **modelo de gestión** y un **manual de condiciones esenciales y procedimientos**.","Exige **procesos documentados, registros, indicadores y mejora**: un SGC del servicio.","Pocos **indicadores bien elegidos**, revisados por la dirección, convierten el papel en sistema."],"referencias":[{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos.","url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf"},{"cita":"Ministerio de Salud y Protección Social. Decreto 780 de 2016, Decreto Único Reglamentario del sector salud.","url":"https://minsalud.gov.co/Normativa/Paginas/decreto-unico-minsalud-780-de-2016.aspx"},{"cita":"Presidencia de la República. Decreto 2200 de 2005: reglamenta el servicio farmacéutico.","url":"https://www.invima.gov.co/sites/default/files/Decreto-2200de-2005.pdf"},{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Tablero ilustrado de indicadores de un servicio farmacéutico con semáforos (dispensación, vencidos, temperatura, pendientes).","alt":"Indicadores del sistema de gestión de calidad del servicio farmacéutico"}],"keywords":["resolución 1403 de 2007","resolución 1403 de 2007 resumen","manual de condiciones esenciales servicio farmacéutico","modelo de gestión del servicio farmacéutico","indicadores servicio farmacéutico","sistema de gestión de calidad droguería"],"proceso":{"titulo":"Montar el SGC del servicio farmacéutico","intro":"Un camino práctico, alineado con el ciclo PHVA.","pasos":[{"titulo":"Diagnosticar","detalle":"Comparar el servicio con el manual de condiciones esenciales y procedimientos de la resolución.","icono":"Search","evidencia":"Diagnóstico con brechas priorizadas."},{"titulo":"Definir política y objetivos","detalle":"La dirección define la política de calidad del servicio y objetivos medibles.","icono":"Flag","evidencia":"Política y objetivos aprobados."},{"titulo":"Documentar procesos","detalle":"Escribir o ajustar procedimientos de cada proceso general y especial.","icono":"FileText","evidencia":"Procedimientos controlados."},{"titulo":"Medir","detalle":"Definir indicadores con fórmula, meta y frecuencia para los procesos críticos.","icono":"BarChart3","evidencia":"Tablero de indicadores."},{"titulo":"Verificar","detalle":"Auditorías internas, seguimiento de no conformidades y revisión por la dirección.","icono":"ClipboardCheck","evidencia":"Informes de auditoría y actas de revisión."},{"titulo":"Mejorar","detalle":"Acciones correctivas y de mejora con verificación de eficacia.","icono":"RefreshCw","evidencia":"Planes de mejora cerrados."}]},"caso":{"titulo":"Los vencidos que nadie veía","contexto":"En el inventario semestral de un servicio farmacéutico hospitalario aparecen medicamentos vencidos por un valor importante. El procedimiento de almacenamiento dice que se debe rotar por fecha de vencimiento.","pregunta":"¿Qué acción refleja mejor el enfoque de la Resolución 1403?","opciones":[{"texto":"Recordar al personal el procedimiento.","correcta":false,"retro":"Recordar no corrige la causa ni permite detectar el problema a tiempo."},{"texto":"Crear un indicador mensual de productos próximos a vencer y vencidos, investigar la causa (rotación, compras, consumo) y definir acciones con seguimiento.","correcta":true,"retro":"Medir y analizar convierte el procedimiento en un proceso gestionado y permite actuar antes de perder el producto."},{"texto":"Esperar al próximo inventario para ver si mejora.","correcta":false,"retro":"Un control semestral es demasiado tardío para un riesgo que se puede medir cada mes."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Resolución 1403 de 2007: sistema de gestión de calidad del servicio farmacéutico$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Resolución 1403 de 2007: sistema de gestión de calidad del servicio farmacéutico$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 14. Introducción a la unidad: modelos de SGC aplicables al sector farmacéutico
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Dos idiomas para un mismo sistema","texto":"Una empresa farmacéutica recibe en el mismo mes una auditoría de su cliente internacional, que pregunta por el sistema de calidad farmacéutico de ICH Q10, y la auditoría de certificación ISO 9001 de su distribuidora. El equipo de calidad siente que debe mantener dos sistemas. No es así: los dos modelos describen el mismo sistema con énfasis distintos. Esta unidad te enseña a leerlos juntos."},"objetivos":["Presentar los dos modelos de SGC más usados en el sector: ICH Q10 e ISO 9001:2015.","Explicar el propósito y el alcance de cada modelo y su relación con las BPM.","Anticipar la ruta de la unidad hacia un sistema integrado."],"conceptos":[{"icono":"Globe","termino":"ICH Q10","definicion":"Guía armonizada que describe un modelo de sistema de calidad farmacéutico para todo el ciclo de vida del producto, complementaria a las BPM. Fue aprobada por el ICH en 2008."},{"icono":"Award","termino":"ISO 9001:2015","definicion":"Norma internacional de requisitos para un sistema de gestión de la calidad, aplicable a cualquier organización y certificable por organismos acreditados."},{"icono":"Factory","termino":"BPM","definicion":"Requisitos obligatorios de fabricación y control de medicamentos. En Colombia, los adoptados por la Resolución 1160 de 2016."},{"icono":"Puzzle","termino":"Sistema integrado","definicion":"Un solo sistema de procesos, documentos y responsables que cumple los requisitos de varias normas a la vez, sin duplicar."}],"secciones":[{"titulo":"ICH Q10: el modelo farmacéutico","parrafos":["ICH Q10 fue desarrollada por las autoridades y la industria de Europa, Japón y Estados Unidos dentro del Consejo Internacional de Armonización. Describe un **sistema de calidad farmacéutico** (PQS, por su sigla en inglés) basado en conceptos de ISO y en las BPM, y aplicable a todo el **ciclo de vida** del producto. No agrega requisitos regulatorios nuevos más allá de las BPM, pero muestra cómo gestionarlas como un sistema.","Su estructura es fácil de recordar: tres objetivos, cuatro etapas del ciclo de vida, dos habilitadores (gestión del conocimiento y gestión de riesgos) y cuatro elementos (monitoreo del desempeño del proceso y la calidad del producto, CAPA, gestión del cambio y revisión por la dirección), todo bajo la **responsabilidad de la dirección**."]},{"titulo":"ISO 9001:2015: el modelo general","parrafos":["ISO 9001:2015 es la norma de requisitos de sistemas de gestión de la calidad más usada en el mundo. Usa la **estructura de alto nivel** común a las normas ISO de sistemas de gestión, con diez cláusulas, y se basa en el enfoque a procesos, el ciclo PHVA y el pensamiento basado en riesgos. Su fortaleza está en la gestión: contexto, partes interesadas, liderazgo, objetivos, competencia, comunicación, auditoría interna y revisión por la dirección.","En el sector farmacéutico, ISO 9001 se usa con frecuencia en distribuidores, operadores logísticos, laboratorios de servicios, proveedores de materiales y servicios farmacéuticos. En las plantas fabricantes, complementa a las BPM y a ICH Q10 con herramientas de gestión."]},{"titulo":"La ruta de la unidad","parrafos":["Recorrerás primero ICH Q10: sus objetivos y la responsabilidad de la dirección, sus habilitadores y sus cuatro elementos, con su equivalente en las BPM europeas y de PIC/S. Luego ISO 9001: estructura de alto nivel, contexto y partes interesadas; liderazgo, política y objetivos; y pensamiento basado en riesgos. La unidad cierra con una comparación y un modelo de integración.","Al terminar podrás explicar a un auditor de cualquiera de los dos marcos cómo tu sistema cumple sus requisitos, señalando los mismos procesos y la misma evidencia."]}],"errores":[{"error":"Pensar que ICH Q10 reemplaza a las BPM.","correccion":"ICH Q10 complementa las BPM: las organiza como sistema para todo el ciclo de vida."},{"error":"Creer que ISO 9001 es suficiente para fabricar medicamentos.","correccion":"ISO 9001 no contiene los requisitos técnicos de BPM, que son obligatorios."}],"comprueba":[{"pregunta":"¿Qué es el PQS?","respuesta":"El sistema de calidad farmacéutico descrito por ICH Q10 para todo el ciclo de vida del producto."},{"pregunta":"¿En qué tipo de organizaciones farmacéuticas es común ISO 9001?","respuesta":"Distribuidores, operadores logísticos, laboratorios de servicios, proveedores y servicios farmacéuticos, entre otros."}],"resumen":["**ICH Q10**: sistema de calidad farmacéutico para el ciclo de vida.","**ISO 9001:2015**: requisitos generales de gestión, certificables.","Un solo **sistema integrado** puede cumplir ambos, junto con las BPM."],"referencias":[{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"}],"imagenes":[{"ubicacion":"Junto a la situación inicial","descripcion":"Dos piezas de rompecabezas (ICH Q10 e ISO 9001) que encajan sobre una base rotulada BPM.","alt":"Integración de ICH Q10, ISO 9001 y BPM en un solo sistema"}],"keywords":["modelos de sistema de gestión de calidad farmacéutica","ich q10 vs iso 9001","sistema de calidad farmacéutico pqs","iso 9001 en la industria farmacéutica","sistema integrado de gestión farmacéutico"],"caso":{"titulo":"Dos auditorías, un sistema","contexto":"El equipo de calidad de un laboratorio propone crear un manual ISO 9001 independiente, con procedimientos propios, para la certificación de su operación logística, separado del sistema BPM de la planta.","pregunta":"¿Qué recomiendas?","opciones":[{"texto":"Hacerlo: cada norma necesita su propio sistema.","correcta":false,"retro":"Dos sistemas paralelos duplican documentos, confunden al personal y suelen contradecirse."},{"texto":"Integrar: un solo mapa de procesos y un solo cuerpo documental, con una matriz que muestre dónde se cumple cada requisito de BPM, ICH Q10 e ISO 9001.","correcta":true,"retro":"La integración evita duplicidades y permite demostrar cumplimiento ante cualquier auditor con la misma evidencia."},{"texto":"Abandonar ISO 9001 porque las BPM son suficientes.","correcta":false,"retro":"Si el negocio requiere la certificación, la solución es integrarla, no renunciar a ella."}]}}$j$::jsonb;
