  END IF;

  -- 16. Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Lo que se va cuando se va una persona","texto":"El químico que desarrolló un producto hace quince años se jubila. Con él se va la explicación de por qué el granulado se seca a esa temperatura y no a otra. Meses después, un cambio aparentemente inocente provoca problemas de disolución, y nadie sabe por qué ocurre. ICH Q10 llama habilitadores a la gestión del conocimiento y a la gestión de riesgos porque sin ellos el sistema decide a ciegas."},"objetivos":["Explicar qué son la gestión del conocimiento y la gestión de riesgos para la calidad dentro del PQS.","Describir el proceso de gestión de riesgos de ICH Q9(R1) y sus actualizaciones de 2023.","Aplicar ambos habilitadores en decisiones típicas del sistema de calidad."],"conceptos":[{"icono":"BookOpen","termino":"Gestión del conocimiento","definicion":"Enfoque sistemático para adquirir, analizar, almacenar y difundir la información sobre productos, procesos y componentes a lo largo del ciclo de vida."},{"icono":"AlertTriangle","termino":"Gestión de riesgos para la calidad","definicion":"Proceso sistemático para evaluar, controlar, comunicar y revisar los riesgos para la calidad del producto a lo largo de su ciclo de vida (ICH Q9)."},{"icono":"Scale","termino":"Formalidad","definicion":"El grado de estructura, documentación y participación que se da a una evaluación de riesgos, proporcional a la incertidumbre, la importancia y la complejidad de la decisión (ICH Q9(R1))."},{"icono":"Eye","termino":"Subjetividad","definicion":"El sesgo que introducen las opiniones y percepciones en la puntuación del riesgo; ICH Q9(R1) pide reconocerlo y controlarlo."}],"secciones":[{"titulo":"Gestión del conocimiento","parrafos":["ICH Q10 define la **gestión del conocimiento** como un enfoque sistemático para adquirir, analizar, almacenar y difundir información sobre productos, procesos de fabricación y componentes. Las fuentes incluyen el conocimiento previo, los estudios de desarrollo, la transferencia de tecnología, la validación, la experiencia de fabricación, la innovación, la mejora continua y las actividades de gestión del cambio.","En la práctica, gestionar el conocimiento es asegurar que las **razones** de las decisiones quedan escritas y disponibles: por qué se eligió ese parámetro, qué se aprendió de una desviación, qué mostró la revisión anual. Herramientas útiles son los informes de desarrollo bien archivados, las bases de lecciones aprendidas de investigaciones, los informes de revisión de producto y los planes de sucesión del conocimiento crítico. La guía de buenas prácticas de ISPE sobre gestión del conocimiento desarrolla métodos concretos."]},{"titulo":"Gestión de riesgos para la calidad","parrafos":["ICH Q9 describe la **gestión de riesgos para la calidad** con dos principios: la evaluación del riesgo debe basarse en el conocimiento científico y vincularse con la protección del paciente, y el nivel de esfuerzo, formalidad y documentación debe ser proporcional al nivel de riesgo. El proceso tiene cuatro componentes: **evaluación** (identificación, análisis y evaluación), **control** (reducción y aceptación), **comunicación** y **revisión**.","La revisión de 2023, **ICH Q9(R1)**, aclaró cuatro temas: la **formalidad** (no toda decisión requiere un análisis complejo, pero el nivel de formalidad debe justificarse), la **subjetividad** en las puntuaciones, la **toma de decisiones basada en riesgo** y los riesgos para la **disponibilidad** del producto, como los que causan desabastecimientos. Herramientas frecuentes son el diagrama de Ishikawa, el análisis de modo y efecto de falla (FMEA), el HACCP y las matrices de riesgo."]},{"titulo":"Los habilitadores en decisiones reales","parrafos":["Un cambio de proveedor de un excipiente es un buen ejemplo de cómo trabajan juntos. La **gestión del conocimiento** aporta lo que se sabe del papel del excipiente en la formulación y de cambios anteriores. La **gestión de riesgos** estructura la evaluación: qué atributos podrían verse afectados, con qué probabilidad y severidad, y qué estudios se necesitan para controlar el riesgo. La decisión queda documentada y alimenta de nuevo el conocimiento.","Lo mismo ocurre al decidir el alcance de una investigación, la frecuencia de un monitoreo ambiental o qué proveedores auditar primero. Cuando estos habilitadores funcionan, el sistema decide con razones; cuando faltan, decide por costumbre o por urgencia."]}],"errores":[{"error":"Puntuar riesgos sin criterios definidos.","correccion":"Define escalas de probabilidad, severidad y detección con descripciones, y controla la subjetividad con revisión por pares."},{"error":"Archivar los informes de desarrollo donde nadie los encuentra.","correccion":"Organiza el conocimiento por producto y vincúlalo con el control de cambios y la revisión anual."},{"error":"Hacer el análisis de riesgo después de decidir, para justificar.","correccion":"El análisis debe informar la decisión, no decorarla."}],"comprueba":[{"pregunta":"¿Cuáles son los dos habilitadores del PQS?","respuesta":"La gestión del conocimiento y la gestión de riesgos para la calidad."},{"pregunta":"¿Qué cuatro temas aclaró ICH Q9(R1) en 2023?","respuesta":"Formalidad, subjetividad, toma de decisiones basada en riesgo y riesgos para la disponibilidad del producto."}],"resumen":["La **gestión del conocimiento** conserva las razones de las decisiones.","La **gestión de riesgos** (ICH Q9) evalúa, controla, comunica y revisa.","La **formalidad** debe ser proporcional al riesgo."],"referencias":[{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ICH. Q9(R1) Quality Risk Management (2023).","url":"https://database.ich.org/sites/default/files/ICH_Q9%28R1%29_Guideline_Step4_2023_0126_0.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Diagrama circular del proceso de gestión de riesgos de ICH Q9 con sus cuatro componentes.","alt":"Proceso de gestión de riesgos para la calidad según ICH Q9"}],"keywords":["gestión del conocimiento farmacéutico","ich q9 r1 gestión de riesgos","gestión de riesgos para la calidad","formalidad ich q9","habilitadores ich q10","fmea industria farmacéutica"],"proceso":{"titulo":"El proceso de gestión de riesgos (ICH Q9)","intro":"Se inicia con una pregunta clara sobre el riesgo y termina con una decisión documentada que se revisa.","pasos":[{"titulo":"Iniciar","detalle":"Definir el problema o la pregunta de riesgo, reunir información y conformar el equipo.","icono":"Flag","evidencia":"Alcance y pregunta de riesgo."},{"titulo":"Identificar","detalle":"Usar información sistemática para identificar peligros: qué podría salir mal.","icono":"Search","evidencia":"Lista de peligros."},{"titulo":"Analizar","detalle":"Estimar la probabilidad y la severidad, y la capacidad de detección cuando aplique.","icono":"Calculator","evidencia":"Análisis con criterios definidos."},{"titulo":"Evaluar","detalle":"Comparar el riesgo estimado con criterios de aceptación.","icono":"Scale","evidencia":"Riesgos priorizados."},{"titulo":"Controlar","detalle":"Reducir el riesgo hasta un nivel aceptable o aceptarlo de forma justificada.","icono":"ShieldCheck","evidencia":"Controles definidos y riesgo residual."},{"titulo":"Comunicar y revisar","detalle":"Compartir el resultado con quienes deciden y revisar el riesgo cuando haya nueva información.","icono":"RefreshCw","evidencia":"Registro de comunicación y revisiones."}]},"caso":{"titulo":"La matriz de riesgo para todo","contexto":"Un laboratorio exige un FMEA completo, con equipo multidisciplinario y tres reuniones, para cualquier cambio, incluido el reemplazo de un termómetro calibrado por otro idéntico. Los cambios importantes esperan semanas por falta de tiempo del equipo.","pregunta":"¿Qué orientación de ICH Q9(R1) aplica?","opciones":[{"texto":"Mantenerlo: más análisis siempre es más seguro.","correcta":false,"retro":"Aplicar la misma formalidad a todo consume recursos que deberían ir a los riesgos importantes."},{"texto":"Ajustar la formalidad al riesgo: análisis simples para decisiones de bajo impacto y FMEA formal para las complejas o inciertas, con criterios escritos.","correcta":true,"retro":"ICH Q9(R1) aclara que la formalidad debe ser proporcional a la incertidumbre, la importancia y la complejidad."},{"texto":"Eliminar los análisis de riesgo para agilizar.","correcta":false,"retro":"Eliminar la gestión de riesgos deja las decisiones sin base; la solución es la proporcionalidad."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Habilitadores del PQS: gestión del conocimiento y gestión de riesgos de calidad$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 17. Los cuatro elementos del PQS y su equivalente en las BPM europeas/PIC/S
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cuatro engranajes que deben girar juntos","texto":"Una planta tiene un excelente sistema de CAPA, pero su control de cambios no consulta las tendencias del proceso, y la dirección revisa indicadores que nadie conecta con las investigaciones. Cada pieza funciona sola, y el sistema no aprende. ICH Q10 describe cuatro elementos que deben girar juntos como engranajes. Esta clase muestra cómo, y dónde aparecen en las BPM europeas y de PIC/S."},"objetivos":["Describir los cuatro elementos del sistema de calidad farmacéutico de ICH Q10.","Explicar cómo se alimentan entre sí.","Ubicar su equivalente en el capítulo 1 de las BPM europeas y de PIC/S."],"conceptos":[{"icono":"LineChart","termino":"Monitoreo del desempeño del proceso y la calidad del producto","definicion":"Sistema para planificar y ejecutar el monitoreo que asegura que el proceso sigue en estado de control e identifica áreas de mejora."},{"icono":"Wrench","termino":"Sistema de acciones correctivas y preventivas (CAPA)","definicion":"Sistema para implementar acciones a partir de la investigación de quejas, rechazos, no conformidades, retiros, desviaciones, auditorías, inspecciones y tendencias."},{"icono":"GitBranch","termino":"Sistema de gestión del cambio","definicion":"Sistema para evaluar, aprobar, implementar y verificar los cambios con base en el conocimiento y la gestión de riesgos."},{"icono":"Users","termino":"Revisión por la dirección","definicion":"Revisión periódica, por parte de la dirección, del desempeño del proceso y la calidad del producto, que asegura que se gestionan a lo largo del ciclo de vida."}],"secciones":[{"titulo":"Los cuatro elementos","parrafos":["El **monitoreo del desempeño del proceso y la calidad del producto** usa la gestión de riesgos para definir una estrategia de control, mide los parámetros y atributos, analiza tendencias, identifica fuentes de variación y retroalimenta el conocimiento. El **sistema CAPA** investiga las quejas, rechazos, no conformidades, retiros, desviaciones, hallazgos de auditorías e inspecciones y tendencias, con un esfuerzo y una formalidad proporcionales al riesgo, y verifica la eficacia de las acciones.","El **sistema de gestión del cambio** evalúa cada cambio propuesto con conocimiento y gestión de riesgos, lo aprueba con la participación de expertos, considera el impacto regulatorio y verifica después de implementarlo que logró su objetivo sin efectos no deseados. La **revisión por la dirección** revisa los resultados de los otros tres, junto con inspecciones, auditorías, quejas y estudios de satisfacción, y toma decisiones y asigna recursos."]},{"titulo":"Cómo se alimentan entre sí","parrafos":["Los elementos forman un ciclo. El **monitoreo** detecta una tendencia, que dispara una investigación en el **sistema CAPA**. La CAPA propone una mejora del proceso, que entra por el **control de cambios**. El cambio se implementa y el **monitoreo** verifica su efecto. La **revisión por la dirección** ve el conjunto y decide prioridades y recursos. Si alguno de los elementos está desconectado, el ciclo se rompe y el sistema deja de aprender.","Una prueba útil en auditoría interna es seguir un hilo: escoger una tendencia, buscar la investigación que generó, la CAPA, el cambio, la verificación de eficacia y la mención en la revisión por la dirección. Si el hilo se corta, ahí está la debilidad del sistema."]},{"titulo":"Su lugar en las BPM europeas y de PIC/S","parrafos":["Las autoridades europeas incorporaron ICH Q10 en el **capítulo 1 de las BPM de la Unión Europea** (EudraLex, volumen 4), titulado sistema de calidad farmacéutico, revisado en 2013, y lo publicaron además como parte III de la guía. La guía de BPM de **PIC/S**, organización que reúne a autoridades de inspección de muchos países, sigue la misma estructura en su capítulo 1. Allí se exigen, entre otros, el monitoreo del proceso, las CAPA, la gestión de cambios, la revisión por la dirección y la **revisión de calidad del producto**.","Para una empresa colombiana que exporta o que recibe auditorías de clientes internacionales, estas guías son la referencia que usarán los auditores. Conocer su capítulo 1 permite demostrar que el sistema local cumple la Resolución 1160 de 2016 y, a la vez, el estándar internacional."]}],"errores":[{"error":"Gestionar CAPA y cambios en sistemas que no se comunican.","correccion":"Vincula cada CAPA que modifica algo con su control de cambios, y viceversa."},{"error":"Revisión por la dirección que solo lee indicadores.","correccion":"Incluye decisiones, responsables y recursos, y su seguimiento en la siguiente revisión."}],"comprueba":[{"pregunta":"¿Cuáles son los cuatro elementos del PQS?","respuesta":"Monitoreo del desempeño del proceso y la calidad del producto, sistema CAPA, sistema de gestión del cambio y revisión por la dirección."},{"pregunta":"¿Dónde se incorporó ICH Q10 en las BPM europeas?","respuesta":"En el capítulo 1 de la EudraLex, volumen 4, sistema de calidad farmacéutico, y como parte III de la guía."}],"resumen":["Cuatro elementos: **monitoreo, CAPA, gestión del cambio y revisión por la dirección**.","Forman un **ciclo**: si uno se desconecta, el sistema no aprende.","Las **BPM europeas y PIC/S** los exigen en su capítulo 1."],"referencias":[{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"Comisión Europea. EudraLex Vol. 4, Capítulo 1: Pharmaceutical Quality System (2013).","url":"https://health.ec.europa.eu/system/files/2016-11/vol4-chap1_2013-01_en_0.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"En la sección de cómo se alimentan","descripcion":"Cuatro engranajes conectados con flechas: monitoreo, CAPA, gestión del cambio y revisión por la dirección.","alt":"Ciclo de los cuatro elementos del sistema de calidad farmacéutico"}],"keywords":["elementos del sistema de calidad farmacéutico","ich q10 capa gestión del cambio","monitoreo del desempeño del proceso","eudralex capítulo 1 sistema de calidad","pics gmp capítulo 1","revisión por la dirección ich q10"],"mapa":{"centro":"Cuatro elementos del PQS","ramas":[{"titulo":"Monitoreo","icono":"LineChart","nodos":["Estrategia de control","Tendencias","Fuentes de variación"]},{"titulo":"CAPA","icono":"Wrench","nodos":["Investigación y causa raíz","Acción proporcional al riesgo","Eficacia"]},{"titulo":"Gestión del cambio","icono":"GitBranch","nodos":["Evaluación con riesgo","Aprobación","Verificación posterior"]},{"titulo":"Revisión por la dirección","icono":"Users","nodos":["Indicadores","Decisiones","Recursos"]}]},"caso":{"titulo":"El hilo que se corta","contexto":"En una auditoría interna se sigue una tendencia de aumento de humedad en un granulado. Hubo investigación y CAPA (ajustar el tiempo de secado), pero el cambio se implementó con una instrucción verbal y la revisión por la dirección nunca lo mencionó.","pregunta":"¿Qué elementos del PQS fallaron?","opciones":[{"texto":"Solo el monitoreo, porque la tendencia tardó en detectarse.","correcta":false,"retro":"El monitoreo sí detectó la tendencia; el problema está después."},{"texto":"La gestión del cambio (cambio sin control ni verificación) y la revisión por la dirección (no conoció ni decidió sobre el tema).","correcta":true,"retro":"La CAPA debió pasar por control de cambios con evaluación, documentación y verificación, y llegar a la revisión por la dirección."},{"texto":"Ninguno, porque el problema se resolvió.","correcta":false,"retro":"Sin control de cambios no hay evidencia de que se resolvió ni de que no causó otros efectos."}]}}$j$::jsonb;
