  END IF;

  -- 28. Caso: ejecutar la revisión por la dirección en un laboratorio colombiano
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"Laboratorio Andino, primer semestre","texto":"Laboratorio Andino es un fabricante ficticio de sólidos orales en Bogotá, con 18 productos y una planta certificada en BPM. Su directora de aseguramiento debe preparar la revisión por la dirección del primer semestre. Tiene los datos, pero también tiene dos problemas: un aumento de quejas por tabletas rotas y una observación del INVIMA sobre el control de cambios. En este caso vas a preparar la revisión, priorizar los temas y formular las decisiones."},"objetivos":["Analizar los datos de un semestre y extraer conclusiones para la dirección.","Priorizar los temas por riesgo para el paciente y para el cumplimiento.","Redactar decisiones de revisión por la dirección con responsable, fecha y recursos."],"conceptos":[{"icono":"BarChart3","termino":"Datos del semestre","definicion":"Aceptación de lotes 96,5 % (antes 98,1 %); quejas por tabletas rotas en el producto X: 14 (antes 3); 22 desviaciones, 6 recurrentes; 78 % de CAPA cerradas en plazo; una observación del INVIMA sobre cambios implementados sin evaluación de impacto."},{"icono":"AlertTriangle","termino":"Riesgos nuevos","definicion":"Rotación de dos analistas senior; proveedor único de un excipiente crítico; actualización normativa pendiente de revisar."},{"icono":"Lightbulb","termino":"Oportunidades","definicion":"Proyecto de registros de lote electrónicos; calificación de un segundo proveedor."}],"secciones":[{"titulo":"Paso 1: analizar, no solo recopilar","parrafos":["La aceptación de lotes bajó 1,6 puntos y coincide con el aumento de quejas por tabletas rotas en el producto X. Al revisar las desviaciones, cuatro de las seis recurrentes son de dureza y friabilidad del mismo producto, y todas se cerraron con «ajuste de la máquina» como acción. La conclusión no es «hay más quejas», sino: **el producto X tiene un problema de proceso no resuelto**, probablemente relacionado con la compresión, y las CAPA no fueron eficaces.","La observación del INVIMA sobre el control de cambios es un tema de **cumplimiento** con riesgo regulatorio directo. La rotación de analistas senior es un **riesgo anticipado** para el laboratorio. El proveedor único es un riesgo de **disponibilidad**. Las oportunidades pueden mejorar la integridad de los datos y la resiliencia del suministro."]},{"titulo":"Paso 2: priorizar por riesgo","parrafos":["Primero lo que afecta al **paciente** y al **cumplimiento**: el problema del producto X (quejas en el mercado) y la observación del INVIMA (plazo de respuesta). Luego lo que puede afectar la **capacidad** del sistema: la rotación en el laboratorio y el proveedor único. Por último, las **oportunidades** que requieren inversión y planificación.","Esta priorización evita que la reunión dedique el mismo tiempo a todo. La agenda puede asignar la mitad del tiempo a los dos primeros temas y presentar los demás con propuestas ya preparadas para aprobar."]},{"titulo":"Paso 3: formular decisiones","parrafos":["Decisiones posibles: (1) abrir una investigación formal del proceso de compresión del producto X con un equipo multidisciplinario, con análisis estadístico de dureza y friabilidad por lote y por máquina, liderada por producción con apoyo de aseguramiento, con informe en 45 días; (2) revisar el procedimiento de control de cambios para hacer obligatoria la evaluación de impacto y capacitar a los responsables, y responder al INVIMA en el plazo, a cargo de aseguramiento; (3) plan de retención y transferencia de conocimiento en el laboratorio, a cargo de talento humano y control de calidad; (4) aprobar la calificación de un segundo proveedor del excipiente, con presupuesto asignado.","Además, la revisión debe registrar el **estado de las acciones** de la revisión anterior, confirmar la **adecuación de los recursos** y concluir sobre la **eficacia del SGC**: en este caso, eficaz en lo general, con una debilidad en la eficacia de las CAPA de proceso y en el control de cambios. Esa conclusión honesta es más valiosa que un «todo dentro de lo esperado»."]}],"errores":[{"error":"Presentar las quejas y las desviaciones como temas separados.","correccion":"Cruza los datos: muchas veces cuentan la misma historia."},{"error":"Cerrar desviaciones recurrentes con «ajuste de máquina».","correccion":"Si se repite, la acción no fue eficaz: hay que investigar la causa raíz."},{"error":"Conclusión de eficacia del sistema sin matices.","correccion":"Di con honestidad dónde funciona el sistema y dónde no."}],"comprueba":[{"pregunta":"¿Qué datos del caso indican un problema de proceso en el producto X?","respuesta":"La caída en la aceptación de lotes, el aumento de quejas por tabletas rotas y las desviaciones recurrentes de dureza y friabilidad."},{"pregunta":"¿Por qué la observación del INVIMA va en la parte alta de la prioridad?","respuesta":"Porque es un riesgo de cumplimiento con plazo de respuesta y puede afectar la certificación."}],"resumen":["**Cruza** los datos: quejas, desviaciones y aceptación de lotes suelen contar la misma historia.","**Prioriza** por riesgo para el paciente y el cumplimiento.","Formula **decisiones** con responsable, fecha y recursos, y concluye con honestidad."],"referencias":[{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"FDA. Submission of Quality Metrics Data: Guidance for Industry (borrador, Rev. 1, 2016).","url":"https://www.fda.gov/media/93012/download"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"}],"imagenes":[{"ubicacion":"En el paso 1","descripcion":"Gráfico ilustrado de quejas por tabletas rotas por mes junto a la dureza promedio por lote del producto X.","alt":"Análisis de datos para una revisión por la dirección en un laboratorio"}],"keywords":["ejemplo de revisión por la dirección","caso práctico revisión por la dirección","revisión por la dirección laboratorio farmacéutico","cómo preparar la revisión por la dirección","acta de revisión gerencial ejemplo"],"caso":{"titulo":"La decisión sobre el producto X","contexto":"En la reunión, el gerente propone resolver las quejas del producto X reforzando la inspección visual en empaque para separar las tabletas rotas.","pregunta":"¿Cuál debe ser la posición de aseguramiento de calidad?","opciones":[{"texto":"Apoyar la propuesta: elimina la queja rápidamente.","correcta":false,"retro":"La inspección es una corrección que no elimina la causa y puede dejar pasar tabletas con defectos no visibles."},{"texto":"Aceptar la inspección como contención temporal, pero exigir la investigación de causa raíz del proceso de compresión con CAPA y verificación de eficacia.","correcta":true,"retro":"Contener mientras se investiga es correcto; la decisión de fondo debe atacar la causa y verificar que el problema no vuelva."},{"texto":"Retirar todo el producto del mercado.","correcta":false,"retro":"Un retiro se decide con base en una evaluación del riesgo para el paciente; no es la primera respuesta ante quejas de este tipo sin esa evaluación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso: ejecutar la revisión por la dirección en un laboratorio colombiano$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Caso: ejecutar la revisión por la dirección en un laboratorio colombiano$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 29. Introducción a la unidad: un SGC vivo que mejora, cambia de forma controlada y se apoya en las personas
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El sistema que se congeló","texto":"Un laboratorio obtuvo su certificación con un sistema impecable. Cinco años después, los procedimientos siguen iguales aunque cambiaron los equipos, la mitad del personal y dos productos. Nadie se atreve a modificar nada por miedo a «salirse del sistema». Un SGC que no mejora ni cambia se vuelve un obstáculo. Esta unidad trata de cómo mantenerlo vivo sin perder el control."},"objetivos":["Explicar por qué un SGC debe mejorar, cambiar de forma controlada y apoyarse en las personas.","Relacionar mejora continua, gestión del cambio y cultura de calidad.","Anticipar la ruta de la unidad y su cierre con una hoja de ruta de implementación."],"conceptos":[{"icono":"RefreshCw","termino":"Mejora continua","definicion":"Actividad recurrente para aumentar el desempeño, a partir de datos, con un ciclo planificado."},{"icono":"GitBranch","termino":"Cambio controlado","definicion":"Un cambio que se evalúa, aprueba, implementa y verifica antes de considerarse cerrado."},{"icono":"Users","termino":"Cultura de calidad","definicion":"Los valores, creencias y comportamientos compartidos que hacen que las personas hagan lo correcto para la calidad aun sin supervisión."}],"secciones":[{"titulo":"Tres fuerzas que mantienen vivo el sistema","parrafos":["Un SGC maduro combina tres fuerzas. La **mejora continua** usa los datos de la unidad anterior (indicadores, desviaciones, quejas, auditorías) para decidir qué mejorar y lo hace con un método. La **gestión del cambio** permite modificar procesos, equipos, proveedores o documentos sin perder el estado de control ni el cumplimiento regulatorio. Y la **cultura de calidad** hace que las personas reporten, propongan y cumplan, porque entienden por qué importa.","Sin mejora, el sistema se estanca. Sin gestión del cambio, la mejora se vuelve un riesgo. Sin cultura, ni la mejora ni los cambios se sostienen. ICH Q10 pone la mejora continua entre sus objetivos y la gestión del cambio entre sus elementos; ISO 9001 dedica su cláusula 10 a la mejora."]},{"titulo":"La ruta de la unidad","parrafos":["Recorrerás el **ciclo PHVA** aplicado a la planta y al servicio farmacéutico; las herramientas de mejora **Kaizen y Lean** y la mejora del desempeño del proceso según ICH Q10; el **sistema de gestión del cambio** de ICH Q10; la **clasificación de cambios** con ICH Q12 y su relación con los trámites ante el INVIMA; la **cultura de calidad** y cómo medirla; y una **hoja de ruta** para implementar o fortalecer un SGC farmacéutico.","Al terminar el curso podrás proponer a tu organización un plan concreto: por dónde empezar, qué medir, cómo gestionar los cambios y cómo involucrar a las personas."]}],"errores":[{"error":"Creer que cumplir es no cambiar nada.","correccion":"El cumplimiento exige cambiar de forma controlada, no congelar el sistema."},{"error":"Hacer mejoras sin pasar por control de cambios.","correccion":"Toda mejora que modifique un proceso o documento entra por gestión del cambio."}],"comprueba":[{"pregunta":"¿Qué tres fuerzas mantienen vivo un SGC?","respuesta":"La mejora continua, la gestión del cambio y la cultura de calidad."}],"resumen":["**Mejora** con datos, **cambia** con control y **apóyate** en las personas.","Un sistema que no cambia se vuelve un **obstáculo**."],"referencias":[{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"},{"cita":"ISPE y PDA. Guide to Improving Quality Culture in Pharmaceutical Manufacturing Facilities (2019).","url":"https://ems.ispe.org/sites/default/files/regulatory/ispe-pda-guide-to-improving-quality-culture.pdf"}],"imagenes":[{"ubicacion":"Junto a la situación inicial","descripcion":"Tres engranajes ilustrados rotulados mejora, cambio y personas, que mueven un sistema de calidad.","alt":"Mejora continua, gestión del cambio y cultura de calidad"}],"keywords":["mejora continua sistema de gestión de calidad","gestión del cambio farmacéutica","cultura de calidad farmacéutica","sistema de calidad vivo","iso 9001 cláusula 10 mejora"],"caso":{"titulo":"El procedimiento intocable","contexto":"Los operarios de empaque proponen un cambio en el orden de las verificaciones del despeje de línea que, según ellos, reduciría errores. La jefatura responde que el procedimiento está aprobado y no se puede tocar.","pregunta":"¿Cuál es la respuesta coherente con un SGC vivo?","opciones":[{"texto":"Mantener el procedimiento: lo aprobado no se cambia.","correcta":false,"retro":"Lo aprobado sí se cambia, pero mediante control de cambios. Rechazar sin evaluar desperdicia el conocimiento de quienes ejecutan."},{"texto":"Registrar la propuesta, evaluarla con control de cambios y, si conviene, implementarla con capacitación y verificación de eficacia.","correcta":true,"retro":"Así se aprovecha la mejora sin perder el control, y se refuerza la cultura de participación."},{"texto":"Dejar que lo cambien de manera informal si funciona.","correcta":false,"retro":"Un cambio informal rompe el control y la trazabilidad, aunque la idea sea buena."}]}}$j$::jsonb;
