  -- 30. Ciclo PHVA aplicado a la planta y al servicio farmacéutico
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cuatro letras que ordenan cualquier mejora","texto":"Un servicio farmacéutico hospitalario tiene demasiados errores de dispensación de medicamentos de alto riesgo. La primera idea es «capacitar a todos». Con el ciclo PHVA, el equipo primero mide y analiza las causas, prueba un cambio en un turno, verifica si funcionó y solo entonces lo extiende. Tres meses después, los errores bajaron y se sabe por qué. Esa disciplina es la que esta clase enseña."},"objetivos":["Describir las cuatro fases del ciclo PHVA y su origen.","Aplicar el ciclo a un problema de una planta y a uno de un servicio farmacéutico.","Reconocer el ciclo PHVA en la estructura de ISO 9001 y en las CAPA."],"conceptos":[{"icono":"ClipboardList","termino":"Planificar","definicion":"Definir el problema y el objetivo, medir la situación actual, analizar las causas y diseñar el cambio con su forma de medirlo."},{"icono":"Hammer","termino":"Hacer","definicion":"Implementar el cambio, de preferencia a pequeña escala o como prueba controlada."},{"icono":"Search","termino":"Verificar","definicion":"Medir los resultados y compararlos con el objetivo y con la situación anterior."},{"icono":"RefreshCw","termino":"Actuar","definicion":"Estandarizar lo que funcionó, corregir lo que no y definir el siguiente ciclo."}],"secciones":[{"titulo":"Origen y lógica del ciclo","parrafos":["El ciclo de mejora nació con Walter Shewhart y lo difundió W. Edwards Deming, que más tarde prefirió hablar de **estudiar** en lugar de verificar para subrayar que se trata de aprender. En español se conoce como **PHVA**: planificar, hacer, verificar y actuar. Su lógica es la del método científico: plantear una hipótesis (si hacemos esto, mejorará aquello), probarla, observar el resultado y decidir.","ISO 9001:2015 se organiza alrededor del ciclo PHVA: planificar con el contexto, el liderazgo y la planificación; hacer con el apoyo y la operación; verificar con la evaluación del desempeño, y actuar con la mejora. Las **CAPA** también son un PHVA: investigar y planificar la acción, implementarla, verificar su eficacia y estandarizar."]},{"titulo":"En la planta","parrafos":["Un ejemplo de planta: la línea de blíster tiene demasiados tiempos muertos en los cambios de formato. **Planificar**: medir la duración de cada cambio por etapas y encontrar que la mitad del tiempo se va en buscar herramientas y en esperar la verificación de despeje. **Hacer**: organizar un carro de herramientas por formato y programar la verificación de calidad. **Verificar**: medir de nuevo los cambios de formato durante un mes. **Actuar**: estandarizar el carro y el horario en el procedimiento, y abordar el siguiente cuello de botella.","La clave es no saltar fases. Muchas mejoras fallan porque se implementan sin línea base (no se sabe si mejoró), sin prueba controlada (el cambio se generaliza antes de saber si funciona) o sin estandarización (lo que funcionó se pierde cuando cambia el turno)."]},{"titulo":"En el servicio farmacéutico","parrafos":["En el servicio farmacéutico, el PHVA ordena las mejoras de la Resolución 1403 de 2007: oportunidad en la dispensación, vencidos, excursiones de temperatura, errores de dispensación. El proceso de la ilustración muestra cómo un problema de medicamentos de aspecto o nombre parecido se aborda con datos, una prueba y una estandarización.","El tamaño del ciclo depende del problema: algunos se resuelven en semanas, otros requieren varios ciclos encadenados. Documentar cada ciclo, aunque sea en una página, construye la memoria de mejora de la organización y alimenta la revisión por la dirección."]}],"errores":[{"error":"Saltar de la idea a la implementación general.","correccion":"Mide, analiza, prueba a pequeña escala y verifica antes de generalizar."},{"error":"No estandarizar lo que funcionó.","correccion":"Actualiza procedimientos, capacita y agrega el control al proceso."}],"comprueba":[{"pregunta":"¿Qué significan las letras PHVA?","respuesta":"Planificar, hacer, verificar y actuar."},{"pregunta":"¿Cómo se relaciona ISO 9001 con el PHVA?","respuesta":"Sus cláusulas se organizan según el ciclo: planificar (4 a 6), hacer (7 y 8), verificar (9) y actuar (10)."}],"resumen":["PHVA: **planificar con datos, hacer en pequeño, verificar y estandarizar**.","Es la lógica de **ISO 9001** y de las **CAPA**.","Funciona igual en la **planta** y en el **servicio farmacéutico**."],"referencias":[{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"},{"cita":"Deming WE. Out of the crisis. Cambridge (MA): MIT Center for Advanced Engineering Study; 1986.","url":""},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos.","url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Rueda PHVA ilustrada con el ejemplo de errores de dispensación en cada cuadrante.","alt":"Ciclo PHVA aplicado a un servicio farmacéutico"}],"keywords":["ciclo phva","ciclo phva ejemplo","phva en farmacia","planificar hacer verificar actuar","ciclo de deming","phva iso 9001"],"proceso":{"titulo":"PHVA para reducir errores de dispensación","intro":"","pasos":[{"titulo":"Planificar: medir","detalle":"Registrar durante un mes los errores de dispensación por tipo, turno y medicamento.","icono":"BarChart3","evidencia":"Línea base de errores."},{"titulo":"Planificar: analizar","detalle":"Usar Pareto e Ishikawa: por ejemplo, la mayoría ocurre con medicamentos de nombre o empaque parecido.","icono":"Search","evidencia":"Causas priorizadas."},{"titulo":"Planificar: diseñar","detalle":"Separar físicamente los medicamentos de aspecto parecido, rotularlos y agregar doble verificación para alto riesgo.","icono":"Lightbulb","evidencia":"Plan del cambio y meta."},{"titulo":"Hacer","detalle":"Probar el cambio en un turno durante un mes, con control de cambios y capacitación.","icono":"Hammer","evidencia":"Registro de la prueba."},{"titulo":"Verificar","detalle":"Comparar los errores del turno piloto con la línea base y con los otros turnos.","icono":"LineChart","evidencia":"Análisis de resultados."},{"titulo":"Actuar","detalle":"Si funcionó, estandarizar en el procedimiento y en todos los turnos; definir el siguiente problema.","icono":"CheckCircle2","evidencia":"Procedimiento actualizado."}]},"caso":{"titulo":"Capacitar a todos","contexto":"Ante un aumento de errores de etiquetado en empaque, la jefatura propone capacitar de nuevo a todo el personal y considerar el problema resuelto.","pregunta":"¿Qué le falta a esa propuesta según el ciclo PHVA?","opciones":[{"texto":"Nada: capacitar es la acción correcta.","correcta":false,"retro":"Sin medir ni analizar causas no se sabe si la falta de capacitación es la causa; y sin verificar, no se sabe si funcionó."},{"texto":"Medir y analizar las causas antes de decidir, probar la acción y verificar su efecto antes de estandarizar.","correcta":true,"retro":"El PHVA exige planificar con datos, probar, verificar y luego estandarizar."},{"texto":"Repetir la capacitación cada mes.","correcta":false,"retro":"Repetir una acción no verificada no garantiza resultados."}]}}$j$::jsonb;
