  -- 35. Hoja de ruta para implementar o fortalecer un SGC farmacéutico
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"Por dónde empezar el lunes","texto":"Terminaste el curso y te asignan una tarea concreta: fortalecer el sistema de calidad de un laboratorio mediano que cumple BPM pero tiene un sistema reactivo, o implementar desde cero el SGC de un servicio farmacéutico. La pregunta práctica es por dónde empezar el lunes. Esta clase integra todo el curso en una hoja de ruta por fases, con entregables y un calendario realista."},"objetivos":["Diseñar una hoja de ruta por fases para implementar o fortalecer un SGC farmacéutico.","Definir los entregables y los indicadores de avance de cada fase.","Identificar los factores que hacen fracasar una implementación y cómo evitarlos."],"conceptos":[{"icono":"Search","termino":"Diagnóstico","definicion":"Evaluación del estado actual frente a los requisitos aplicables (BPM, ICH Q10, ISO 9001, servicio farmacéutico) y la cultura."},{"icono":"Route","termino":"Hoja de ruta","definicion":"Plan por fases con objetivos, entregables, responsables y fechas."},{"icono":"Flag","termino":"Victorias tempranas","definicion":"Mejoras visibles y de bajo costo que generan confianza en el proyecto."},{"icono":"Award","termino":"Certificación","definicion":"Evaluación por un organismo independiente. En Colombia, los organismos de certificación ISO son acreditados por el ONAC; la certificación BPM la otorga el INVIMA."}],"secciones":[{"titulo":"Empieza por el diagnóstico y el compromiso","parrafos":["Ninguna implementación funciona sin **patrocinio de la dirección**: tiempo, recursos y presencia. La primera fase consigue ese compromiso con un diagnóstico honesto: compara la situación con los requisitos aplicables (Resolución 1160 de 2016 si fabrica, Resolución 3619 de 2013 si tiene laboratorio, Decreto 780 de 2016 y Resolución 1403 de 2007 si tiene servicio farmacéutico, más ICH Q10 e ISO 9001 según sus metas) y mide la cultura. El resultado es una lista de brechas priorizadas por riesgo para el paciente y para el cumplimiento.","Con el diagnóstico se diseña el sistema: contexto, partes interesadas, política, objetivos, **mapa de procesos** y **matriz de requisitos legales**. Estos entregables orientan todo lo demás y evitan escribir procedimientos sin saber para qué proceso son."]},{"titulo":"Los procesos críticos primero","parrafos":["No todo se implementa a la vez. Los procesos que más protegen al paciente y que más pesan en una inspección son los primeros: **desviaciones y CAPA**, **control de cambios**, **control documental**, **quejas y retiros**, y **liberación**. Con ellos funcionando, el sistema ya aprende de sus problemas. Luego vienen la medición con un **tablero de indicadores**, la **competencia** del personal y los **recorridos de liderazgo**.","Conviene buscar **victorias tempranas**: un tablero visual en el área de empaque, la eliminación de un formato duplicado, la reducción del tiempo de cierre de desviaciones. Generan confianza y demuestran que el sistema ayuda en lugar de estorbar."]},{"titulo":"Verificar, consolidar y evitar los fracasos típicos","parrafos":["La primera **autoinspección o auditoría interna** completa y la primera **revisión por la dirección** son el momento de verificar si el sistema funciona. Sus hallazgos alimentan la fase de consolidación. Si la organización busca la **certificación ISO 9001**, elige un organismo de certificación acreditado por el ONAC; la certificación de BPM la otorga el INVIMA según el Decreto 335 de 2022.","Los fracasos típicos son conocidos: implementar para la auditoría y no para el negocio, escribir demasiados documentos, dejar el proyecto solo en manos de calidad, no medir y no sostener. La mejor protección es un sistema sencillo, centrado en los procesos críticos, con dueños, indicadores y una dirección que revisa y decide. Ese es el SGC que este curso te ha enseñado a construir."]}],"errores":[{"error":"Implementar para la auditoría.","correccion":"Implementa para el negocio y el paciente; la auditoría verificará un sistema que ya funciona."},{"error":"Dejar el proyecto solo a calidad.","correccion":"Asigna dueños de proceso en todas las áreas y patrocinio de la dirección."},{"error":"No sostener después de la certificación.","correccion":"Mantén la revisión por la dirección, las auditorías y los proyectos de mejora."}],"comprueba":[{"pregunta":"¿Qué procesos conviene implementar primero?","respuesta":"Desviaciones y CAPA, control de cambios, control documental, quejas y retiros, y liberación."},{"pregunta":"¿Quién acredita a los organismos de certificación ISO en Colombia?","respuesta":"El ONAC, Organismo Nacional de Acreditación de Colombia."}],"resumen":["Empieza por **compromiso y diagnóstico**; diseña con **mapa de procesos** y **matriz legal**.","Implementa **primero los procesos críticos** y busca **victorias tempranas**.","**Verifica, consolida y sostén**: un sistema sencillo que funciona vale más que uno extenso en papel."],"referencias":[{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"ISO. ISO 9001:2015 Sistemas de gestión de la calidad — Requisitos.","url":"https://www.iso.org/standard/62085.html"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"},{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos.","url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf"},{"cita":"Presidencia de la República. Decreto 335 de 2022: procedimiento para obtener los certificados de cumplimiento de buenas prácticas.","url":"https://www.invima.gov.co/sites/default/files/medicamentos-y-productos-biologicos/tecnico-medicamentos/medicamentos-sintesis-quimica-y-biologica/Decreto%20No.%20335%20de%202022.pdf"}],"imagenes":[{"ubicacion":"Junto al proceso","descripcion":"Hoja de ruta ilustrada en seis fases sobre una línea de tiempo de doce meses, con entregables en cada fase.","alt":"Hoja de ruta para implementar un sistema de gestión de calidad farmacéutico"}],"keywords":["cómo implementar un sistema de gestión de calidad","hoja de ruta sgc farmacéutico","implementación iso 9001 pasos","fortalecer sistema de calidad farmacéutico","plan de implementación de calidad","certificación iso 9001 colombia onac"],"proceso":{"titulo":"Hoja de ruta en seis fases","intro":"Los plazos son orientativos para una organización mediana; se ajustan a su tamaño y punto de partida.","pasos":[{"titulo":"Fase 1. Compromiso y diagnóstico (mes 1 y 2)","detalle":"Patrocinio de la dirección, equipo líder, diagnóstico frente a los requisitos aplicables y encuesta de cultura.","icono":"Search","evidencia":"Informe de diagnóstico con brechas priorizadas."},{"titulo":"Fase 2. Diseño del sistema (mes 2 y 3)","detalle":"Contexto, partes interesadas, política, objetivos, mapa de procesos y matriz de requisitos legales.","icono":"Route","evidencia":"Mapa de procesos y política aprobados."},{"titulo":"Fase 3. Procesos críticos primero (mes 3 a 6)","detalle":"Desviaciones y CAPA, control de cambios, control documental, quejas y retiros, con sus indicadores.","icono":"Workflow","evidencia":"Procedimientos vigentes y registros en uso."},{"titulo":"Fase 4. Medición y competencia (mes 4 a 8)","detalle":"Tablero de indicadores, programa de capacitación por competencias y recorridos de liderazgo.","icono":"BarChart3","evidencia":"Tablero en uso y capacitación registrada."},{"titulo":"Fase 5. Verificación (mes 8 a 10)","detalle":"Autoinspección o auditoría interna completa y primera revisión por la dirección.","icono":"ClipboardCheck","evidencia":"Informe de auditoría y acta de revisión."},{"titulo":"Fase 6. Consolidación y mejora (mes 10 en adelante)","detalle":"Cierre de hallazgos, proyectos de mejora, revisión de producto y, si aplica, certificación.","icono":"RefreshCw","evidencia":"Plan de mejora y resultados."}]},"caso":{"titulo":"Cien procedimientos en tres meses","contexto":"Un consultor propone a un laboratorio escribir cien procedimientos nuevos en tres meses para «tener el sistema completo» antes de la recertificación.","pregunta":"¿Qué le responderías a la gerencia?","opciones":[{"texto":"Aceptar: más documentos dan más cumplimiento.","correcta":false,"retro":"Cien documentos nuevos sin implementar ni capacitar generan incumplimientos con su propio sistema."},{"texto":"Priorizar: diagnóstico de brechas, procesos críticos primero con procedimientos que se usen y se midan, y una autoinspección antes de la visita.","correcta":true,"retro":"Un sistema sencillo, implementado y medido es más sólido que un sistema extenso en papel."},{"texto":"Posponer todo hasta después de la recertificación.","correcta":false,"retro":"Postergar deja las brechas abiertas justo cuando más importan."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Hoja de ruta para implementar o fortalecer un SGC farmacéutico$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Hoja de ruta para implementar o fortalecer un SGC farmacéutico$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (181_experiencias_gestion_calidad.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Gestión de Calidad Farmacéutica$t$, v_n;
END $exp$;
